(() => {
  'use strict';
  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const main=$('#main'), nav=$('#nav'), title=$('#pageTitle'), sub=$('#pageSub'), modal=$('#modal'), modalTitle=$('#modalTitle'), modalDesc=$('#modalDesc'), modalBody=$('#modalBody');
  let state=null, view='Dashboard', adminTab='division', settingsTab='update', periodPageMonth=today().slice(0,7), draft={date:today(),amount:'',transaction_scope:'',school_id:'',supplier_id:'',transaction_type:'',source_fund_id:''}, review=null, transactionFocusId=null;
  const transactionCache=new Map(),historyCache=new Map();
  const txListState={page:1,per_page:50,q:'',status:'all',month:''};
  const reportState={rows:[],summary:{gross:0,base:0,business:0,ewt:0,total:0},total:0,truncated:false};
  const classifications=['Supplier of Goods','Supplier of Services','Rental','Contractor','Utilities','Other'];
  const viewTitles={'Action Center':['Division Action Center','Review pending Division work from one place; existing bell notifications remain available.'],Dashboard:['Withholding overview','Checked totals are based on Division-reviewed records available to your account.'],Transactions:['Transaction register','Drafts, submitted transactions, checked records, pending approvals, edit history and void records.'],'Transaction Periods':['Monthly transaction periods','Open, close and selectively reopen transaction months for schools and Division Office.'],Suppliers:['Supplier master','Shared supplier/payee information used by all participating schools.'],'ATC Master':['ATC master','Shared tax codes, classifications, rates and effective dates.'],Schools:['Participating schools','School profiles and authorized representative information.'],Reports:['Withholding reports','Filter, print and export withholding records for reconciliation.'],Administration:['Workspace administration','Division profile, authorized accounts, audit history and source-of-fund configuration.'],'System Settings':['System settings','Application updates and read-only SQL diagnostics.'],'My Account':['My account','Maintain your sign-in username, recovery email and password. You can sign in with either your username or recovery email.']};
  const navItems=['Dashboard','Action Center','Transactions','Transaction Periods','Suppliers','ATC Master','Schools','Reports','Administration','System Settings','My Account'];

  function h(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
  function money(c=0){return new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(Number(c||0)/100);}
  function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
  function fmtDateTime(v){if(!v)return '—';try{return new Date(v).toLocaleString('en-PH',{timeZone:'Asia/Manila'});}catch{return v;}}
  function active(x){return Number(x?.active)!==0;}
  function toast(msg,kind=''){const d=document.createElement('div');d.className='toast-item '+kind;d.textContent=msg;$('#toast').appendChild(d);setTimeout(()=>d.remove(),4200);}
  function errorHtml(e){return `<div class="notice error">${h(e?.message||e)}</div>`;}
  function statusText(s){return String(s||'')==='deleted'?'cancelled':String(s||'').replaceAll('_',' ');}
  function statusBadge(s){return `<span class="status ${h(s)}">${h(statusText(s))}</span>`;}
  function periodStateText(s){return ({not_opened:'not opened',open:'open',closed:'closed / locked',reopened:'reopened'})[String(s||'')]||String(s||'not opened').replaceAll('_',' ');}
  function periodStateBadge(s){const stateName=String(s||'not_opened');return `<span class="status period-${h(stateName)}">${h(periodStateText(stateName))}</span>`;}
  function period_isWritableClient(s){return ['open','reopened'].includes(String(s||''));}
  function hasPending(t){return !!t?.pending_edit;}
  function transactionBadges(t){return `${statusBadge(t.status)}${hasPending(t)?'<span class="status pending">pending approval</span>':''}${t?.deletion_request?'<span class="status delete-pending">cancellation pending</span>':''}`;}
  function transactionStatusText(t){const base=statusText(t?.status);return t?.deletion_request?`${base} / cancellation pending`:(hasPending(t)?`${base} / pending approval`:base);}
  function pendingNotifications(){return [...(state?.notifications||[])];}
  // Match the Action Center's existing "Items requiring attention" total.
  // The notification bell intentionally includes waiting-for-another-reviewer notices.
  function actionCenterAttentionCount(){
    return isAdmin()?pendingNotifications().filter(n=>divisionActionGroup(n)!=='waiting').length:0;
  }
  function updateActionCenterNavBadge(){
    const link=nav?.querySelector('[data-view="Action Center"]');
    if(!link)return;
    const badge=link.querySelector('.action-center-nav-badge');
    if(!badge)return;
    const count=actionCenterAttentionCount();
    badge.textContent=count>99?'99+':String(count);
    badge.hidden=count===0;
    link.setAttribute('aria-label',count?`Action Center, ${count} item${count===1?'':'s'} requiring attention`:'Action Center, no items requiring attention');
  }
  function renderNotifications(){
    const btn=$('#notificationBtn'),badge=$('#notificationBadge'),panel=$('#notificationPanel');if(!btn||!badge||!panel||!state)return;
    const items=pendingNotifications(),count=items.length;badge.textContent=count>99?'99+':String(count);badge.hidden=count===0;btn.setAttribute('aria-label',count?`${count} pending notification${count===1?'':'s'}`:'No pending notifications');
    panel.innerHTML=`<div class="notification-head"><strong>Pending notifications</strong><span class="notification-count">${count} item${count===1?'':'s'}</span></div>${items.length?`<div class="notification-list">${items.map(n=>`<button type="button" class="notification-item" data-notification-id="${h(n.id)}" data-notification-type="${h(n.type||'transaction')}"><span class="notification-item-title"><span>${h(n.title)}</span><span class="notification-dot ${h(n.kind)}" aria-hidden="true"></span></span><span class="notification-item-meta">${h(n.meta)}</span><span class="notification-item-detail">${h(n.detail)}</span></button>`).join('')}</div>`:'<div class="notification-empty">Nothing is pending right now.</div>'}`;
    $$('[data-notification-id]',panel).forEach(el=>el.onclick=()=>{const id=el.dataset.notificationId,type=el.dataset.notificationType;panel.hidden=true;btn.setAttribute('aria-expanded','false');if(type==='password_reset'){view='Administration';adminTab='accounts';renderNav();render();setTimeout(()=>document.querySelector(`[data-reset-id="${id}"]`)?.scrollIntoView({block:'center',behavior:'smooth'}),80);return;}if(type==='period'){if(isAdmin()){view='Transaction Periods';const m=String(id||'').split(':')[1];if(/^\d{4}-\d{2}$/.test(m||''))periodPageMonth=m;}else view='Dashboard';renderNav();render();return;}view='Transactions';transactionFocusId=id;renderNav();render();setTimeout(()=>openTransaction(id),80);});
    updateActionCenterNavBadge();
  }
  function selectOptions(items,valueLabel=(x)=>x.name,includeBlank='Select'){return `<option value="">${h(includeBlank)}</option>`+items.map(x=>`<option value="${h(x.id)}">${h(valueLabel(x))}</option>`).join('');}
  function isOwner(){return state?.actor?.role==='project_owner';}
  function isAdmin(){return ['project_owner','division_admin'].includes(state?.actor?.role);}
  function roleLabel(role){return ({project_owner:'Project Owner',division_admin:'Division Admin',school_user:'School User'})[role]||String(role||'');}
  function schoolName(id){return state?.schools?.find(x=>x.id===id)?.name||id||'—';}
  function transactionScope(t){const saved=String(t?.transaction_scope||t?.snapshot?.transaction_scope||'').trim();if(saved==='division'||saved==='school')return saved;return t?.school_id?'school':'division';}
  function transactionOriginName(t){return transactionScope(t)==='division'?(t?.snapshot?.division?.name||state?.division?.name||'Division Office'):(t?.snapshot?.school?.name||schoolName(t?.school_id));}
  function supplierName(id){return state?.suppliers?.find(x=>x.id===id)?.name||id||'—';}
  function supplierForTransaction(t){const snap=t?.snapshot?.supplier;if(snap&&typeof snap==='object')return snap;return state?.suppliers?.find(x=>x.id===t?.supplier_id)||{name:supplierName(t?.supplier_id),vat_status:'',tin:''};}
  function supplierTaxStatus(value){const s=String(value||'').trim();if(!s)return '';if(/^non[-\s]?vat/i.test(s))return 'Non-VAT';if(/^vat/i.test(s))return 'VAT';return s.replace(/\s+Registered$/i,'');}
  function formatSupplierTin(value){const raw=String(value??'').trim(),d=raw.replace(/\D/g,'');if(d.length===14)return `${d.slice(0,3)}-${d.slice(3,6)}-${d.slice(6,9)}-${d.slice(9,14)}`;if(d.length===12)return `${d.slice(0,3)}-${d.slice(3,6)}-${d.slice(6,9)}-${d.slice(9,12)}`;if(d.length===9)return `${d.slice(0,3)}-${d.slice(3,6)}-${d.slice(6,9)}`;return raw;}
  function transactionReference(t){const saved=String(t?.reference||t?.snapshot?.transaction_reference||'').trim();if(saved)return saved;const id=String(t?.id||'');return id?`${id.slice(0,12)}…`:'—';}
  function supplierDisplayHtml(t){const s=supplierForTransaction(t),name=s?.name||supplierName(t?.supplier_id),meta=[supplierTaxStatus(s?.vat_status),formatSupplierTin(s?.tin)].filter(Boolean).join(' · ');return `<strong>${h(name)}</strong>${meta?`<div class="master-meta">${h(meta)}</div>`:''}`;}
  function csvCell(value){let s=String(value??'');if(/^[=+\-@]/.test(s.trimStart()))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
  function atcName(id){return state?.atcs?.find(x=>x.id===id)?.name||id||'—';}
  function atcWithRate(id){const a=state?.atcs?.find(x=>x.id===id);return a?`${a.name} (${a.rate}%)`:(id||'—');}
  function sourceFundName(id){return state?.source_funds?.find(x=>x.id===id)?.name||id||'—';}
  function supplierProfiles(s){const raw=Array.isArray(s?.transaction_profiles)?s.transaction_profiles.filter(x=>x&&x.transaction_type&&x.business_atc&&x.ewt_atc):[];if(raw.length)return raw.map(x=>({transaction_type:String(x.transaction_type),business_atc:String(x.business_atc),ewt_atc:String(x.ewt_atc)}));if(s?.transaction_type&&s?.business_atc&&s?.ewt_atc)return [{transaction_type:String(s.transaction_type),business_atc:String(s.business_atc),ewt_atc:String(s.ewt_atc)}];return [];}
  function supplierProfile(s,type=''){const profiles=supplierProfiles(s),wanted=String(type||'');if(wanted){const found=profiles.find(x=>x.transaction_type===wanted);if(found)return found;if(profiles.length===1)return profiles[0];return null;}if(profiles.length===1)return profiles[0];const legacy=String(s?.transaction_type||'');return profiles.find(x=>x.transaction_type===legacy)||profiles[0]||null;}
  function transactionTypeForRow(t){return String(t?.transaction_type||t?.snapshot?.transaction_type||t?.snapshot?.supplier?.transaction_type||'');}
  function shortTransactionType(type){return String(type||'').replace(/^Supplier of /,'');}
  function supplierProfileMeta(profile){return profile?`${shortTransactionType(profile.transaction_type)} · VAT ${atcWithRate(profile.business_atc)} · EWT ${atcWithRate(profile.ewt_atc)}`:'No transaction tax profile configured';}
  function snapshotAtcLabel(atc){if(!atc)return '—';const code=atc.name||'—',rate=atc.rate!==undefined&&atc.rate!==null&&String(atc.rate)!==''?`${atc.rate}%`:'',description=String(atc.description||'').trim();return [code,rate,description].filter(Boolean).join(' · ');}
  function snapshotEncodingDetailsHtml(s){const sp=s?.supplier||{},address=[sp.address,sp.zip].filter(Boolean).join(' · ');return `<div class="notice"><strong>Business type:</strong> ${h(sp.business_type||'—')}<br><strong>VAT ATC:</strong> ${h(snapshotAtcLabel(s?.business))}<br><strong>EWT ATC:</strong> ${h(snapshotAtcLabel(s?.ewt))}${address?`<br><strong>Supplier address:</strong> ${h(address)}`:''}</div>`;}
  function duplicateMatchLine(d){const ref=String(d.reference||'').trim()||`${String(d.id||'').slice(0,12)}…`;return `${String(d.status||'').replaceAll('_',' ')} · ${d.source_fund||'Source fund unavailable'} · ${shortTransactionType(d.transaction_type)||'Transaction type unavailable'} · ${money(d.gross)} · Ref ${ref}`;}
  function duplicateWarningHtml(matches){const rows=Array.isArray(matches)?matches:[];if(!rows.length)return '';return `<div class="notice warn"><strong>Possible duplicate transaction.</strong><br><span>This origin already has ${rows.length} non-void transaction${rows.length===1?'':'s'} with the same supplier, transaction date and gross amount. This is only a warning—legitimate separate transactions are allowed.</span><div class="duplicate-match-list">${rows.map(d=>`<div class="master-meta">${h(duplicateMatchLine(d))}</div>`).join('')}</div></div>`;}
  function duplicateConfirmationText(matches){const rows=Array.isArray(matches)?matches:[];const details=rows.slice(0,8).map(d=>'• '+duplicateMatchLine(d)).join('\n');return `Possible duplicate transaction detected.\n\nAnother non-void transaction uses the same origin, supplier, date and gross amount.${details?'\n\n'+details:''}\n\nThis can still be a valid separate transaction. Submit anyway?`;}
  function amountToCentsLocal(value){const n=Number(String(value??'').replace(/,/g,'').trim());return Number.isFinite(n)?Math.round((n+Number.EPSILON)*100):NaN;}
  function draftMatchesTransaction(t){return !!t&&transactionScope(t)===String(draft.transaction_scope||transactionScope(t))&&String(t.supplier_id||'')===String(draft.supplier_id||'')&&String(transactionTypeForRow(t)||'')===String(draft.transaction_type||'')&&String(t.source_fund_id||'')===String(draft.source_fund_id||'')&&String(t.date||'')===String(draft.date||'')&&Number(t.gross||0)===amountToCentsLocal(draft.amount);}
  function divisionLogoUrl(){const d=state?.division||{};if(!d.logo_path)return '';const stamp=d.logo_updated_at?encodeURIComponent(String(d.logo_updated_at)):'';return stamp?`logo.php?v=${stamp}`:'logo.php';}
  function txAmounts(t){return t?.snapshot?.amounts||t?.display_amounts||null;}
  function renderBranding(){const url=divisionLogoUrl();[['.brand-logo-wrap','brand-logo'],['.topbar-logo-wrap','topbar-logo']].forEach(([wrapSel,imgClass])=>{const wrap=$(wrapSel);if(!wrap)return;wrap.innerHTML=url?`<img class="${imgClass}" src="${h(url)}" alt="Division logo">`:`<div class="brand-mark ${imgClass==='topbar-logo'?'topbar-mark':''}">WT</div>`;});}
  function readFileAsDataUrl(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=()=>reject(Error('The selected image could not be read.'));reader.readAsDataURL(file);});}

  function cacheTransactions(rows=[]){for(const t of rows||[])if(t?.id)transactionCache.set(t.id,t);return rows||[];}
  function cachedTransaction(id){return transactionCache.get(id)||null;}
  async function apiGet(params={}){const qs=new URLSearchParams(params);const r=await fetch('api.php?'+qs.toString(),{headers:{'Accept':'application/json'},cache:'no-store'});const j=await r.json().catch(()=>({error:'Invalid server response.'}));if(r.status===401){location.href='login.php';throw Error('Your session expired. Please sign in again.');}if(!r.ok)throw Error(j.error||'Request failed.');if(j.csrf){window.NONIUS.csrf=j.csrf;if(state)state.csrf=j.csrf;}return j;}
  async function fetchTransaction(id){const j=await apiGet({scope:'transaction',id});cacheTransactions([j.transaction]);return j.transaction;}
  async function fetchHistory(id,force=false){if(!force&&historyCache.has(id))return historyCache.get(id);const j=await apiGet({scope:'history',id});historyCache.set(id,j.history||[]);return j.history||[];}
  async function refreshNotifications(){try{const j=await apiGet({scope:'notifications'});if(state){state.notifications=j.notifications||[];if(Array.isArray(j.password_reset_requests))state.password_reset_requests=j.password_reset_requests;renderNotifications();}}catch(e){if(e.message&&!/session expired/i.test(e.message))console.warn('Notification refresh failed:',e.message);}}

  async function api(body){const opts={headers:{'Accept':'application/json'}};if(body){opts.method='POST';opts.headers['Content-Type']='application/json';opts.headers['X-CSRF-Token']=state?.csrf||window.NONIUS.csrf;opts.body=JSON.stringify(body);}const r=await fetch('api.php',opts);const j=await r.json().catch(()=>({error:'Invalid server response.'}));if(r.status===401){location.href='login.php';throw Error('Your session expired. Please sign in again.');}if(!r.ok){const err=Error(j.error||'Request failed.');err.code=j.code||'';err.supplier=j.supplier||null;throw err;}return j;}
  async function load(){try{state=await api();window.NONIUS.csrf=state.csrf;transactionCache.clear();historyCache.clear();cacheTransactions(state.transactions||[]);renderBranding();renderNav();render();renderNotifications();$('#who').innerHTML=`<div class="who-email">${h(state.actor.username||'')}</div>${state.actor.email?`<div class="who-role">${h(state.actor.email)}</div>`:''}<div class="who-role">${h(roleLabel(state.actor.role))}</div>`;}catch(e){main.innerHTML=errorHtml(e);}}
  async function mutate(body,success){try{const r=await api(body);await load();if(success)toast(success);return r;}catch(e){if(e.code!=='SUPPLIER_TIN_EXISTS')toast(e.message,'error');throw e;}}

  function visibleNav(){if(isOwner())return navItems;if(isAdmin())return ['Dashboard','Action Center','Transactions','Transaction Periods','Suppliers','ATC Master','Schools','Reports','Administration','My Account'];return ['Dashboard','Transactions','Suppliers','ATC Master','Reports','My Account'];}
  function renderNav(){nav.className='nav';nav.innerHTML=visibleNav().map(v=>`<a href="#" class="nav-link ${view===v?'active':''}" data-view="${h(v)}">${h(v)}${v==='Action Center'?'<span class="action-center-nav-badge" aria-hidden="true" hidden></span>':''}</a>`).join('');$$('[data-view]',nav).forEach(a=>a.onclick=e=>{e.preventDefault();go(a.dataset.view);});updateActionCenterNavBadge();}
  function go(v){view=v;renderNav();render();document.body.classList.remove('sidebar-open');}
  function startNewTransaction(){draft={date:today(),amount:'',transaction_scope:isAdmin()?'division':'school',school_id:isAdmin()?'':state?.actor?.school_id||'',supplier_id:'',transaction_type:'',source_fund_id:''};review=null;renderGenerate();}
  function render(){const [t,s]=viewTitles[view]||[view,''];title.textContent=t;sub.textContent=s;try{({'Action Center':renderActionCenter,Dashboard:renderDashboard,Transactions:renderTransactions,'Transaction Periods':renderPeriods,Suppliers:()=>renderMaster('suppliers'),'ATC Master':()=>renderMaster('atcs'),Schools:()=>renderMaster('schools'),Reports:renderReports,Administration:renderAdmin,'System Settings':renderSystem,'My Account':renderMyAccount}[view]||renderDashboard)();}catch(e){main.innerHTML=errorHtml(e);}}

  // Division Action Center shares the exact role-scoped notification feed with the bell.
  // It does not introduce another approval path, mutate data, or alter bell notifications.
  function divisionActionGroup(n){
    if(n.kind==='waiting')return 'waiting';
    if(n.type==='password_reset')return 'password';
    if(n.type==='period')return 'period';
    switch(String(n.title||'')){
      case 'Submitted for checking':return 'submitted';
      case 'School edit awaiting approval':return 'edits';
      case 'Cancellation request awaiting approval':return 'cancellations';
      case 'Division Draft not yet checked':return 'division';
      default:return 'other'; // Never silently discard newly added notice categories.
    }
  }
  function openDivisionAction(n){
    if(!n)return;
    if(n.type==='password_reset'){
      view='Administration';adminTab='accounts';renderNav();render();
      setTimeout(()=>document.querySelector(`[data-reset-id="${CSS.escape(String(n.id||''))}"]`)?.scrollIntoView({block:'center',behavior:'smooth'}),80);
      return;
    }
    if(n.type==='period'){
      view='Transaction Periods';const m=String(n.id||'').split(':')[1];
      if(/^\d{4}-\d{2}$/.test(m||''))periodPageMonth=m;
      renderNav();render();return;
    }
    view='Transactions';transactionFocusId=String(n.id||'');renderNav();render();
    setTimeout(()=>openTransaction(n.id),80);
  }
  function renderActionCenter(){
    if(!isAdmin()){
      main.innerHTML='<div class="notice error">Division Action Center is available only to authorized Division users.</div>';
      return;
    }
    const items=pendingNotifications();
    const groups=[
      ['submitted','Submitted for checking','School submissions awaiting Division checking'],
      ['edits','Pending Checked edits','Proposed school changes requiring Division approval'],
      ['cancellations','Cancellation requests','Checked transactions awaiting a cancellation decision'],
      ['password','Password reset requests','Accounts awaiting an authorized Division decision'],
      ['division','Division drafts','Division-level drafts that still need checking'],
      ['period','Period setup reminders','First opening of a new transaction month'],
      ['other','Other actions','Additional pending notifications'],
      ['waiting','Awaiting another reviewer','Visible for awareness; action must be taken by another authorized user']
    ];
    const categorized=items.map(n=>({...n,actionGroup:divisionActionGroup(n)}));
    const count=key=>categorized.filter(n=>n.actionGroup===key).length;
    const actionable=actionCenterAttentionCount();
    const cardKeys=['submitted','edits','cancellations','password'];
    main.innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Division Action Center</h2><p class="muted small">The same pending items shown by the notification bell, organized for Division review. Actions open the existing secure transaction, account, or period workflow.</p></div><button type="button" class="secondary" id="actionCenterRefresh">Refresh actions</button></div><div class="cards action-center-cards"><div class="card"><div class="label">Items requiring attention</div><div class="value">${actionable}</div></div>${cardKeys.map(key=>{const label=groups.find(g=>g[0]===key)[1];return `<div class="card"><div class="label">${h(label)}</div><div class="value">${count(key)}</div></div>`;}).join('')}</div>${!categorized.length?'<div class="notice success">No pending Division items right now.</div>':''}<div class="action-center-sections">${groups.map(([key,label,description])=>{const rows=categorized.filter(n=>n.actionGroup===key);if(!rows.length)return '';return `<section class="action-center-group" aria-label="${h(label)}"><div class="panel-head"><div><h3>${h(label)} <span class="action-center-count">${rows.length}</span></h3><p class="muted small">${h(description)}</p></div></div><div class="action-center-list">${rows.map(n=>{return `<div class="action-center-item"><div><strong>${h(n.title)}</strong><div class="action-center-meta">${h(n.meta||'')}</div><div class="action-center-detail">${h(n.detail||'')}</div></div><button type="button" class="secondary action-center-open" data-action-id="${h(n.id)}" data-action-type="${h(n.type||'transaction')}">${key==='waiting'?'View':'Open'}</button></div>`;}).join('')}</div></section>`;}).join('')}</div></section>`;
    $('#actionCenterRefresh').onclick=async()=>{const b=$('#actionCenterRefresh');b.disabled=true;try{const j=await apiGet({scope:'notifications'});state.notifications=j.notifications||[];if(Array.isArray(j.password_reset_requests))state.password_reset_requests=j.password_reset_requests;renderNotifications();if(view==='Action Center')renderActionCenter();toast('Pending items refreshed.');}catch(e){toast(e.message,'error');if(b)b.disabled=false;}};
    $$('.action-center-open',main).forEach(button=>button.onclick=()=>{
      const n=items.find(x=>String(x.id)===button.dataset.actionId&&String(x.type||'transaction')===button.dataset.actionType);
      if(n)openDivisionAction(n);
    });
  }

  function renderDashboard(){const period=state.transaction_period||{},periodState=isAdmin()?String(period.division_state||'not_opened'):String(period.state||'not_opened'),periodClass=isAdmin()?(Number(period.not_opened_targets||0)===Number(period.total_targets||0)&&Number(period.total_targets||0)>0?'warn':(Number(period.not_opened_targets||0)===0?'success':'')):(periodState==='open'?'success':(periodState==='reopened'?'warn':periodState==='closed'?'success':'warn'));let periodNotice='';if(isAdmin())periodNotice=`<div class="notice ${periodClass}"><div class="panel-head"><div><strong>${h(period.label||period.month||'Current month')} transaction periods</strong><div class="small">${Number(period.open_targets||0)} open/reopened · ${Number(period.closed_targets||0)} closed/locked · ${Number(period.not_opened_targets||0)} not opened. Division Office: ${h(periodStateText(periodState))}.</div></div><button class="secondary" id="managePeriods" type="button">Manage periods</button></div></div>`;else periodNotice=`<div class="notice ${periodClass}"><strong>${h(period.label||period.month||'Current month')} — ${h(periodStateText(periodState))}</strong><br><span class="small">${periodState==='closed'?'This month is locked. The Division must reopen it before transactions dated in this month can be changed.':periodState==='not_opened'?'Wait for the Division to open this month before entering transactions.':'Transactions dated in this month are allowed for your school.'}</span></div>`;const d=state.dashboard||{summary:{},recent:[]},sum=d.summary||{},tx=cacheTransactions(d.recent||[]);main.innerHTML=`${periodNotice}<div class="cards"><div class="card"><div class="label">Checked transactions</div><div class="value">${Number(sum.count||0)}</div></div><div class="card"><div class="label">Gross amount</div><div class="value">${money(sum.gross||0)}</div></div><div class="card"><div class="label">VAT withheld</div><div class="value">${money(sum.business||0)}</div></div><div class="card"><div class="label">Expanded withholding</div><div class="value">${money(sum.ewt||0)}</div></div></div><section class="panel"><div class="panel-head"><div><div class="kicker">Total taxes withheld</div><h2>${money(sum.total||0)}</h2></div><button class="primary" id="newTx">New transaction</button></div><div class="table-wrap">${tx.length?`<table><thead><tr><th>Date</th><th>Origin</th><th>Source of Fund</th><th>Supplier</th><th>Status</th><th>Gross</th><th>Tax Base</th><th>VAT</th><th>EWT</th><th>Total Tax Withheld</th><th></th></tr></thead><tbody>${tx.map(t=>{const a=txAmounts(t);return `<tr><td>${h(t.date)}<div class="master-meta">Ref ${h(transactionReference(t))}</div></td><td>${h(transactionOriginName(t))}</td><td>${h(t.snapshot?.source_fund?.name||sourceFundName(t.source_fund_id))}</td><td>${supplierDisplayHtml(t)}</td><td><div class="status-stack">${transactionBadges(t)}</div></td><td>${money(t.gross)}</td><td>${a?money(a.base):'—'}</td><td>${a?money(a.business):'—'}</td><td>${a?money(a.ewt):'—'}</td><td><strong>${a?money(a.total):'—'}</strong></td><td><div class="actions compact-actions table-action-icons"><button class="secondary table-action-icon tx-detail" data-id="${h(t.id)}" type="button" aria-label="Open transaction" title="Open transaction"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5c5.2 0 9.3 4.4 10.5 6a1.7 1.7 0 0 1 0 2C21.3 14.6 17.2 19 12 19S2.7 14.6 1.5 13a1.7 1.7 0 0 1 0-2C2.7 9.4 6.8 5 12 5Zm0 2C8 7 4.6 10.2 3.3 12 4.6 13.8 8 17 12 17s7.4-3.2 8.7-5C19.4 10.2 16 7 12 7Zm0 2.25A2.75 2.75 0 1 1 12 14.75 2.75 2.75 0 0 1 12 9.25Z"/></svg></button><button class="secondary table-action-icon dashboard-print" data-id="${h(t.id)}" type="button" aria-label="Print Form 2307" title="Print Form 2307"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 3h10a2 2 0 0 1 2 2v3h1a3 3 0 0 1 3 3v5a3 3 0 0 1-3 3h-1v2H5v-2H4a3 3 0 0 1-3-3v-5a3 3 0 0 1 3-3h1V5a2 2 0 0 1 2-2Zm0 5h10V5H7v3Zm0 11h10v-5H7v5Zm12-2h1a1 1 0 0 0 1-1v-5a1 1 0 0 0-1-1H4a1 1 0 0 0-1 1v5a1 1 0 0 0 1 1h1v-5h14v5Zm0-5.5a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"/></svg></button></div></td></tr>`;}).join('')}</tbody></table>`:'<div class="empty">No checked transactions yet.</div>'}</div></section>${!state.division&&isAdmin()?'<div class="notice warn">Complete the Division Office payor profile before checking transactions. Open Administration.</div>':''}`;if($('#managePeriods'))$('#managePeriods').onclick=()=>go('Transaction Periods');$('#newTx').onclick=startNewTransaction;$$('.tx-detail').forEach(b=>b.onclick=()=>openTransaction(b.dataset.id));$$('.dashboard-print').forEach(b=>b.onclick=async()=>{try{const t=await fetchTransaction(b.dataset.id);await printCertificate(t);}catch(e){toast(e.message,'error');}});}

  function renderGenerate(){
    const suppliers=(state.suppliers||[]).filter(active), sourceFunds=(state.source_funds||[]).filter(active);
    const selected=state.suppliers.find(s=>s.id===draft.supplier_id), current=draft.id?cachedTransaction(draft.id):null, pending=current?.pending_edit||null;
    const scope=current?transactionScope(current):(draft.transaction_scope|| (isAdmin()?'division':'school'));draft.transaction_scope=scope;draft.school_id=scope==='school'?(current?.school_id||state?.actor?.school_id||''):'';
    const profiles=selected?supplierProfiles(selected):[];if(selected&&!draft.transaction_type&&profiles.length===1)draft.transaction_type=profiles[0].transaction_type;const selectedProfile=selected?supplierProfile(selected,draft.transaction_type):null;
    const transactionTypeField=selected&&profiles.length>1?`<label class="required-transaction-field"><span>Transaction type <strong aria-hidden="true">*</strong></span><select id="txTransactionType" required><option value="">Select transaction type</option>${profiles.map(p=>`<option value="${h(p.transaction_type)}" ${p.transaction_type===draft.transaction_type?'selected':''}>${h(shortTransactionType(p.transaction_type))}</option>`).join('')}</select><small class="muted">This supplier has multiple tax profiles. Choose whether this payment is for Goods, Services, or another configured type.</small></label>`:'';
    const noProfiles=selected&&profiles.length===0?'<div class="notice error"><strong>This supplier has no transaction tax profile.</strong><br>Update the Supplier master before creating a transaction.</div>':'';
    const noFunds=sourceFunds.length===0?'<div class="notice warn"><strong>No active Source of Fund is configured.</strong><br>Ask a Division Administrator to add or activate one under Administration → Source of Fund.</div>':'';
    const divisionReady=!!(state.division?.representative&&state.division?.designation&&state.division?.representative_tin);
    const divisionProfileNotice=scope==='division'&&!divisionReady?'<div class="notice warn"><strong>Division representative profile is incomplete.</strong><br>Before this Division-level transaction can be checked or printed on Form 2307, complete Representative, Designation and Representative TIN under Administration → Division Profile.</div>':'';
    const sourceFundField=`<label class="required-transaction-field"><span>Source of Fund <strong aria-hidden="true">*</strong></span><select id="txSourceFund" name="source_fund_id" required aria-required="true">${selectOptions(sourceFunds,x=>x.name,'Select source of fund')}</select><small class="muted">Required for every withholding transaction.</small></label>`;
    const status=current?.status||'';
    const periodOverview=state.transaction_period||{},selectedMonth=String(draft.date||today()).slice(0,7);let periodAccessNotice='';
    if(selectedMonth===String(periodOverview.month||'')){
      const ps=scope==='division'?String(periodOverview.division_state||'not_opened'):(!isAdmin()?String(periodOverview.state||'not_opened'):'');
      if(ps){const pc=ps==='open'?'success':(ps==='reopened'?'warn':ps==='closed'?'error':'warn');periodAccessNotice=`<div class="notice ${pc}"><strong>${h(periodOverview.label||selectedMonth)} period: ${h(periodStateText(ps))}</strong><br><span class="small">${period_isWritableClient(ps)?'This transaction date is currently permitted.':ps==='closed'?'This month is locked. The Division must reopen it before this transaction can be changed.':'The Division must open this month before transactions dated here can be created or changed.'}</span></div>`;}
    }
    let workflowNotice='';
    if(status==='draft'&&scope==='division') workflowNotice='<div class="notice"><strong>Status: Division Draft.</strong><br>Review or revise the calculation. When it is correct, use Mark Checked to finalize this Division-level transaction.</div>';
    else if(status==='draft') workflowNotice='<div class="notice"><strong>Status: Draft.</strong><br>Review or revise the details, click Generate & Calculate again when needed, then submit only when the calculation is correct.</div>';
    if(status==='submitted') workflowNotice='<div class="notice"><strong>Status: Submitted.</strong><br>This school transaction is waiting for Division checking. School edits create a revision Draft while preserving the last Submitted values so the Draft can be discarded if needed.</div>';
    if(status==='returned') workflowNotice='<div class="notice warn"><strong>Status: Returned for Correction.</strong><br>Review the Division remarks in the transaction history, make the requested correction, then resubmit it for checking.</div>';
    if(status==='draft'&&current?.submitted_backup) workflowNotice='<div class="notice warn"><strong>Revision Draft.</strong><br>The last Submitted version is preserved. You may continue revising and resubmit, or discard this Draft to restore the previous Submitted values.</div>';
    if(status==='checked'&&!pending&&scope==='school') workflowNotice='<div class="notice warn"><strong>This is a checked transaction.</strong><br>The checked version remains the official record. Saving changes creates a pending edit that requires Division approval before it replaces the checked version.</div>';
    if(status==='checked'&&pending) workflowNotice='<div class="notice warn"><strong>Pending changes are awaiting Division approval.</strong><br>You may revise the pending changes again. The last checked version remains the official record until the Division approves the edit.</div>';
    const buttonLabel=status==='checked'?(pending?'Update pending changes':'Submit changes for approval'):'Generate & Calculate';
    const originBlock=scope==='division'?`<div><div class="kicker">Transaction origin</div><strong>${h(state.division?.name||'Division Office')}</strong><div class="master-meta">Division-level transaction</div></div>`:`<div><div class="kicker">Originating school</div><strong>${h(current?transactionOriginName(current):(state.schools[0]?.name||'Assigned school'))}</strong></div>`;
    modalTitle.textContent=current?'Edit transaction':(scope==='division'?'New Division transaction':'New transaction');
    modalDesc.textContent=scope==='division'?'Generate and review a Division Office withholding transaction.':'Generate, review and submit withholding transactions for Division checking.';
    modal.style.width='min(1180px,calc(100% - 2rem))';
    modalBody.innerHTML=`<div class="split"><section class="panel"><div class="panel-head"><h2>Transaction details</h2>${current?`<div class="actions compact-actions">${transactionBadges(current)}</div>`:''}</div>${workflowNotice}${periodAccessNotice}${divisionProfileNotice}${noFunds}<form id="txForm" class="stack">${originBlock}${sourceFundField}<label>Supplier / Payee<select id="txSupplier" required>${selectOptions(suppliers,x=>`${x.name} · ${x.tin}`,'Select supplier')}</select></label>${transactionTypeField}${noProfiles}<div class="grid2"><label>Transaction date<input id="txDate" type="date" required value="${h(draft.date||today())}"></label><label>Gross amount (PHP)<input id="txAmount" inputmode="decimal" required placeholder="0.00" value="${h(draft.amount||'')}"></label></div>${selected&&selectedProfile?`<div class="notice"><strong>${h(selected.name)}</strong><br><span class="muted">${h(selected.vat_status)} · ${h(supplierProfileMeta(selectedProfile))}</span></div>`:''}<div class="actions"><button class="primary" type="submit" ${sourceFunds.length&&(!selected||profiles.length>0)?'':'disabled'}>${h(buttonLabel)}</button>${current?.status==='checked'&&pending&&!isAdmin()?'<button class="secondary" type="button" id="cancelPendingEdit">Cancel pending changes</button>':''}${current?.status==='draft'&&current?.submitted_backup?'<button class="secondary" type="button" id="discardSubmittedDraft">Discard Draft</button>':''}${draft.id?'<button class="secondary" type="button" id="resetDraft">Start new</button>':''}</div></form></section><section class="panel" id="reviewPanel">${review?reviewMarkup(review,current):`<div class="empty"><strong>Computation preview</strong><p>Complete the transaction details and click Generate & Calculate. The record will be saved as Draft first so you can review the tax calculation before ${scope==='division'?'marking it Checked.':'submitting it to the Division.'}</p></div>`}</section></div>`;
    if(!modal.open)modal.showModal();
    const sourceSelect=$('#txSourceFund');if(!sourceSelect)throw new Error('Source of Fund field could not be loaded. Reload the application.');sourceSelect.value=draft.source_fund_id||'';
    $('#txSupplier').value=draft.supplier_id||'';
    $('#txSupplier').onchange=e=>{draft.date=$('#txDate').value;draft.amount=$('#txAmount').value;draft.transaction_scope=scope;draft.school_id=scope==='school'?(current?.school_id||state.actor.school_id):'';draft.source_fund_id=$('#txSourceFund').value;draft.supplier_id=e.target.value;const next=state.suppliers.find(s=>s.id===draft.supplier_id),nextProfiles=next?supplierProfiles(next):[];draft.transaction_type=nextProfiles.length===1?nextProfiles[0].transaction_type:'';review=null;renderGenerate();};
    if($('#txTransactionType'))$('#txTransactionType').onchange=e=>{draft.date=$('#txDate').value;draft.amount=$('#txAmount').value;draft.transaction_scope=scope;draft.school_id=scope==='school'?(current?.school_id||state.actor.school_id):'';draft.source_fund_id=$('#txSourceFund').value;draft.transaction_type=e.target.value;review=null;renderGenerate();};
    $('#txDate').onchange=e=>{draft.date=e.target.value;draft.amount=$('#txAmount').value;draft.transaction_scope=scope;draft.school_id=scope==='school'?(current?.school_id||state.actor.school_id):'';draft.source_fund_id=$('#txSourceFund').value;draft.supplier_id=$('#txSupplier').value;draft.transaction_type=$('#txTransactionType')?.value||draft.transaction_type;review=null;renderGenerate();};
    $('#txForm').onsubmit=async e=>{e.preventDefault();draft.date=$('#txDate').value;draft.amount=$('#txAmount').value;draft.supplier_id=$('#txSupplier').value;draft.transaction_type=$('#txTransactionType')?.value||supplierProfile(state.suppliers.find(s=>s.id===draft.supplier_id),draft.transaction_type)?.transaction_type||'';draft.source_fund_id=$('#txSourceFund').value;draft.transaction_scope=scope;draft.school_id=scope==='school'?(current?.school_id||state.actor.school_id):'';try{const before=draft.id?cachedTransaction(draft.id):null;const changed=before?!draftMatchesTransaction(before):true;if(before?.status==='submitted'&&changed&&!confirm('Editing this Submitted transaction will return it to Draft until you submit it again. Continue?'))return;const action=before?.status==='checked'?'saveTransaction':'saveDraft';const payload={action,id:draft.id||undefined,version:before?.version,pending_version:before?.pending_edit?.version,transaction_scope:draft.transaction_scope,school_id:draft.school_id||null,supplier_id:draft.supplier_id,transaction_type:draft.transaction_type,source_fund_id:draft.source_fund_id,date:draft.date,amount:draft.amount};let save=await api(payload);if(save?.duplicate_warning){if(!confirm(duplicateConfirmationText(save.duplicates)))return;save=await api({...payload,duplicate_confirmed:true});}draft.id=save.id;const updated=await fetchTransaction(draft.id);draft.transaction_scope=transactionScope(updated);draft.school_id=updated.school_id||'';await refreshNotifications();if(['draft','submitted','returned'].includes(updated?.status))review=await api({action:'preview',id:draft.id});else if(updated?.status==='checked'&&updated?.pending_edit)review=await api({action:'previewPending',id:draft.id});else review=updated?.snapshot?{snapshot:updated.snapshot}:null;renderGenerate();// The calculation dialog must stay open so the user can decide whether to submit.
      // Refresh the Transactions page behind it only after save + preview succeed.
      txListState.q='';txListState.status='all';txListState.month='';txListState.page=1;
      transactionFocusId=updated.id;go('Transactions');
      let message=transactionScope(updated)==='division'?'Division Draft saved and calculation generated. Review it, then Mark Checked.':'Draft saved and calculation generated. Review it before submitting.';if(save.returned_to_draft)message='Transaction returned to Draft and recalculated. Submit it again when the calculation is correct.';else if(save.cancelled)message='Pending changes cancelled. The last checked version remains official.';else if(save.pending&&save.unchanged)message='No changes were detected in the pending edit.';else if(save.pending&&save.duplicate_warning_acknowledged)message='Changes submitted for Division approval. Possible duplicate warning was acknowledged and recorded.';else if(save.pending)message='Changes submitted for Division approval. The last checked version remains official.';else if(save.unchanged&&updated?.status==='submitted')message='No changes detected. The transaction remains Submitted and no edit history was recorded.';else if(save.unchanged&&updated?.status==='checked')message='No changes detected. The checked transaction remains unchanged and no edit history was recorded.';else if(save.unchanged)message='No changes detected. The Draft remains unchanged and no edit history was recorded.';toast(message);}catch(err){toast(err.message,'error');}};
    if($('#submitDraft'))$('#submitDraft').onclick=async()=>{const t=cachedTransaction(draft.id);if(!t||transactionScope(t)!=='school'||!['draft','returned'].includes(t.status))return;if(!confirm(t.status==='returned'?'Resubmit this corrected transaction to the Division for checking?':'Submit this Draft to the Division for checking?'))return;try{const submittedId=t.id,payload={action:'submitTransaction',id:t.id,version:t.version};let result=await api(payload);if(result?.duplicate_warning){if(!confirm(duplicateConfirmationText(result.duplicates)))return;result=await api({...payload,duplicate_confirmed:true});}await refreshNotifications();draft={date:today(),amount:'',transaction_scope:isAdmin()?'division':'school',school_id:isAdmin()?'':state?.actor?.school_id||'',supplier_id:'',transaction_type:'',source_fund_id:''};review=null;transactionFocusId=submittedId;modal.close();modal.style.width='';go('Transactions');toast(result?.duplicate_warning_acknowledged?'Transaction submitted. Possible duplicate warning was acknowledged and recorded.':(t.status==='returned'?'Corrected transaction resubmitted for Division checking.':'Transaction submitted for Division checking.'));}catch(err){toast(err.message,'error');}};
    if($('#checkDivisionDraft'))$('#checkDivisionDraft').onclick=async()=>{const t=cachedTransaction(draft.id);if(!t||transactionScope(t)!=='division'||t.status!=='draft')return;if(!confirm('Mark this Division-level transaction as Checked? The current calculation and Division representative data will be frozen for Form 2307.'))return;try{const payload={action:'check',id:t.id,version:t.version,remarks:''};let result=await api(payload);if(result?.duplicate_warning){if(!confirm(duplicateConfirmationText(result.duplicates)))return;result=await api({...payload,duplicate_confirmed:true});}await refreshNotifications();const checkedId=t.id;draft={date:today(),amount:'',transaction_scope:'division',school_id:'',supplier_id:'',transaction_type:'',source_fund_id:''};review=null;transactionFocusId=checkedId;modal.close();modal.style.width='';go('Transactions');toast(result?.duplicate_warning_acknowledged?'Division transaction checked. Possible duplicate warning was acknowledged and recorded.':'Division transaction marked Checked.');}catch(err){toast(err.message,'error');}};
    if($('#cancelPendingEdit'))$('#cancelPendingEdit').onclick=async()=>{const t=cachedTransaction(draft.id);if(!t?.pending_edit)return;if(!confirm('Cancel these pending changes? The proposed revision will be discarded and the last Checked version will remain official. This action will still be recorded in transaction history.'))return;try{await api({action:'cancelPendingEdit',id:t.id,version:t.version,pending_version:t.pending_edit.version});const restored=await fetchTransaction(t.id);await refreshNotifications();draft={id:restored.id,date:restored.date,amount:(Number(restored.gross)/100).toFixed(2),transaction_scope:transactionScope(restored),school_id:restored.school_id||'',supplier_id:restored.supplier_id,transaction_type:transactionTypeForRow(restored),source_fund_id:restored.source_fund_id||''};review=restored?.snapshot?{snapshot:restored.snapshot}:null;renderGenerate();toast('Pending changes cancelled. The last Checked version remains official.');}catch(err){toast(err.message,'error');}};
    if($('#discardSubmittedDraft'))$('#discardSubmittedDraft').onclick=async()=>{const t=cachedTransaction(draft.id);if(!t?.submitted_backup)return;if(!confirm('Discard this revision Draft and restore the last Submitted version? All unsent Draft changes will be removed.'))return;try{await api({action:'discardSubmittedDraft',id:t.id,version:t.version});const restored=await fetchTransaction(t.id);await refreshNotifications();draft={id:restored.id,date:restored.date,amount:(Number(restored.gross)/100).toFixed(2),transaction_scope:transactionScope(restored),school_id:restored.school_id||'',supplier_id:restored.supplier_id,transaction_type:transactionTypeForRow(restored),source_fund_id:restored.source_fund_id||''};review=await api({action:'preview',id:restored.id});renderGenerate();toast('Draft discarded. The previous Submitted version was restored.');}catch(err){toast(err.message,'error');}};
    if($('#resetDraft'))$('#resetDraft').onclick=()=>{draft={date:today(),amount:'',transaction_scope:isAdmin()?'division':'school',school_id:isAdmin()?'':state.actor.school_id,supplier_id:'',transaction_type:'',source_fund_id:''};review=null;renderGenerate();};
  }

  function reviewMarkup(p,current=null){
    const s=p.snapshot,a=s.amounts,duplicateNotice=duplicateWarningHtml(p.duplicate_candidates),scope=current?transactionScope(current):(s.transaction_scope||'school');
    const rep=s.representative||{name:s.school?.representative||'',position:s.school?.position||'',tin:s.school?.representative_tin||''};
    let workflow='';
    if(current?.status==='checked'&&current?.pending_edit) workflow='<div class="notice warn"><strong>Pending approval.</strong> These proposed values are not yet the official checked record. The last checked version remains valid until the Division approves this edit.</div>';
    else if(current?.status==='checked') workflow='<div class="notice success">This version is checked and Form 2307 is available from the Transactions register.</div>';
    else if(current?.status==='draft'&&scope==='division') workflow='<div class="notice"><strong>Status: Division Draft.</strong> Review the computation and representative information below. When correct, mark this Division-level transaction Checked.</div><div class="actions"><button class="primary" type="button" id="checkDivisionDraft">Mark Checked</button></div>';
    else if(current?.status==='draft') workflow='<div class="notice"><strong>Status: Draft.</strong> Review the computation below. If it is correct, submit this Draft to the Division for checking.</div><div class="actions"><button class="primary" type="button" id="submitDraft">Submit for checking</button></div>';
    else if(current?.status==='submitted') workflow='<div class="notice warn">Status: Submitted. A Division user must review this transaction and mark it Checked before Form 2307 is treated as the approved record.</div>';
    else if(current?.status==='returned') workflow='<div class="notice warn"><strong>Status: Returned for Correction.</strong> Make the requested correction, review the computation, then resubmit it to the Division.</div><div class="actions"><button class="primary" type="button" id="submitDraft">Resubmit for checking</button></div>';
    return `<div class="panel-head"><div><div class="kicker">${current?.status==='checked'&&current?.pending_edit?'Pending computation':'Computation preview'}</div><h2>${h(s.supplier.name)}</h2><div class="master-meta">${h(supplierTaxStatus(s.supplier?.vat_status)||'—')} · TIN ${h(formatSupplierTin(s.supplier?.tin)||'—')}</div>${current?`<div class="master-meta">Ref ${h(transactionReference(current))}</div>`:''}</div></div><div class="notice"><strong>Origin:</strong> ${h(scope==='division'?(s.division?.name||'Division Office'):(s.school?.name||'School'))}<br><strong>Source of Fund:</strong> ${h(s.source_fund?.name||'—')}<br><strong>Transaction type:</strong> ${h(shortTransactionType(s.transaction_type||s.supplier?.transaction_type)||'—')}</div>${duplicateNotice}${snapshotEncodingDetailsHtml(s)}<div class="review"><div class="review-row"><span>Gross amount</span><strong>${money(a.gross)}</strong></div><div class="review-row"><span>Tax base</span><strong>${money(a.base)}</strong></div><div class="review-row"><span>VAT withheld · ${h(s.business.name)} (${h(s.business.rate)}%)</span><strong>${money(a.business)}</strong></div><div class="review-row"><span>Expanded withholding · ${h(s.ewt.name)} (${h(s.ewt.rate)}%)</span><strong>${money(a.ewt)}</strong></div><div class="review-row"><span>Total taxes withheld</span><strong>${money(a.total)}</strong></div><div class="review-row"><span>Net payment</span><strong>${money(a.net)}</strong></div></div><div class="notice"><strong>Official payor:</strong> ${h(s.division.name)}<br><span class="muted">TIN ${h(formatSupplierTin(s.division.tin)||s.division.tin)} · ${h(s.division.address)}</span><br><strong>2307 representative:</strong> ${h(rep.name||'—')} · ${h(rep.position||'—')}${rep.tin?` · TIN ${h(formatSupplierTin(rep.tin)||rep.tin)}`:''}</div>${workflow}`;
  }

  function renderTransactions(){
    main.innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Transaction register</h2><p class="muted small">Drafts, submitted, returned-for-correction, checked records and pending approvals available to your account. Cancelled records are hidden from All statuses and remain available through the Cancelled filter for audit.</p></div><button class="primary" id="newTxFromTransactions">New Transaction</button></div><div class="toolbar"><label>Search<input id="txSearch" placeholder="Supplier, origin, source of fund, reference" value="${h(txListState.q)}"></label><label>Status<select id="txStatus"><option value="all">All statuses</option><option value="draft">draft</option><option value="submitted">submitted</option><option value="returned">returned for correction</option><option value="checked">checked</option><option value="pending">pending approval</option><option value="void">void</option><option value="deleted">cancelled</option></select></label><label>Month<input id="txMonth" type="month" value="${h(txListState.month)}"></label><label>Rows<select id="txPerPage"><option value="25">25</option><option value="50">50</option><option value="100">100</option></select></label></div><div id="txSummary"></div><div id="txTable"><div class="loading">Loading transactions…</div></div><div id="txPager"></div></section>`;
    $('#newTxFromTransactions').onclick=startNewTransaction;$('#txStatus').value=txListState.status;$('#txPerPage').value=String(txListState.per_page);
    let requestSerial=0,searchTimer=null;
    const loadPage=async()=>{
      const serial=++requestSerial;$('#txTable').innerHTML='<div class="loading">Loading transactions…</div>';
      try{
        const j=await apiGet({scope:'transactions',page:txListState.page,per_page:txListState.per_page,q:txListState.q,status:txListState.status,month:txListState.month});if(serial!==requestSerial||view!=='Transactions'||!$('#txTable'))return;
        const rows=cacheTransactions(j.rows||[]),pg=j.pagination||{page:1,pages:1,total:rows.length,per_page:txListState.per_page},sum=j.summary||{};txListState.page=Number(pg.page||1);
        $('#txSummary').innerHTML=`<div class="cards"><div class="card"><div class="label">Displayed gross</div><div class="value">${money(sum.gross||0)}</div></div><div class="card"><div class="label">VAT withheld</div><div class="value">${money(sum.business||0)}</div></div><div class="card"><div class="label">EWT</div><div class="value">${money(sum.ewt||0)}</div></div><div class="card"><div class="label">Total tax withheld</div><div class="value">${money(sum.total||0)}</div></div></div>`;
        $('#txTable').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Date</th>${isAdmin()?'<th>Origin</th>':''}<th>Source of Fund</th><th>Supplier</th><th>Gross</th><th>VAT</th><th>EWT</th><th>Total Tax Withheld</th><th>Status</th><th>Reference</th><th></th></tr></thead><tbody>${rows.map(t=>{const a=txAmounts(t);return `<tr data-tx-row="${h(t.id)}" class="${transactionFocusId===t.id?'transaction-focus':''}"><td>${h(t.date)}</td>${isAdmin()?`<td>${h(transactionOriginName(t))}</td>`:''}<td>${h(t.snapshot?.source_fund?.name||sourceFundName(t.source_fund_id))}</td><td>${h(t.snapshot?.supplier?.name||supplierName(t.supplier_id))}</td><td>${money(t.gross)}</td><td>${a?money(a.business):'—'}</td><td>${a?money(a.ewt):'—'}</td><td><strong>${a?money(a.total):'—'}</strong></td><td><div class="status-stack">${transactionBadges(t)}</div></td><td class="master-meta"><strong>${h(transactionReference(t))}</strong></td><td><div class="actions compact-actions table-action-icons"><button class="secondary table-action-icon tx-detail" data-id="${h(t.id)}" type="button" aria-label="Open transaction" title="Open transaction"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5c5.2 0 9.3 4.4 10.5 6a1.7 1.7 0 0 1 0 2C21.3 14.6 17.2 19 12 19S2.7 14.6 1.5 13a1.7 1.7 0 0 1 0-2C2.7 9.4 6.8 5 12 5Zm0 2C8 7 4.6 10.2 3.3 12 4.6 13.8 8 17 12 17s7.4-3.2 8.7-5C19.4 10.2 16 7 12 7Zm0 2.25A2.75 2.75 0 1 1 12 14.75 2.75 2.75 0 0 1 12 9.25Z"/></svg></button>${['submitted','checked','void'].includes(t.status)?`<button class="secondary table-action-icon tx-print" data-id="${h(t.id)}" type="button" aria-label="Print Form 2307" title="Print Form 2307"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 3h10a2 2 0 0 1 2 2v3h1a3 3 0 0 1 3 3v5a3 3 0 0 1-3 3h-1v2H5v-2H4a3 3 0 0 1-3-3v-5a3 3 0 0 1 3-3h1V5a2 2 0 0 1 2-2Zm0 5h10V5H7v3Zm0 11h10v-5H7v5Zm12-2h1a1 1 0 0 0 1-1v-5a1 1 0 0 0-1-1H4a1 1 0 0 0-1 1v5a1 1 0 0 0 1 1h1v-5h14v5Zm0-5.5a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"/></svg></button>`:''}</div></td></tr>`;}).join('')}</tbody></table></div>`:'<div class="empty">No matching transactions.</div>';
        const pages=Number(pg.pages||1),page=Number(pg.page||1);$('#txPager').innerHTML=`<div class="panel-head compact-pager"><span class="muted small">${Number(pg.total||0)} transaction${Number(pg.total||0)===1?'':'s'} · Page ${page} of ${pages}</span><div class="actions compact-actions"><button class="secondary" id="txPrev" ${page<=1?'disabled':''}>Previous</button><button class="secondary" id="txNext" ${page>=pages?'disabled':''}>Next</button></div></div>`;
        $('#txPrev').onclick=()=>{if(txListState.page>1){txListState.page--;loadPage();}};$('#txNext').onclick=()=>{if(txListState.page<pages){txListState.page++;loadPage();}};
        $$('.tx-detail',$('#txTable')).forEach(b=>b.onclick=()=>openTransaction(b.dataset.id));
        $$('.tx-print',$('#txTable')).forEach(b=>b.onclick=async()=>{try{const t=await fetchTransaction(b.dataset.id);await printCertificate(t);}catch(e){toast(e.message,'error');}});
        if(transactionFocusId){const row=$(`[data-tx-row="${transactionFocusId}"]`,$('#txTable'));if(row){requestAnimationFrame(()=>row.scrollIntoView({behavior:'smooth',block:'center'}));setTimeout(()=>row.classList.remove('transaction-focus'),4500);}transactionFocusId=null;}
      }catch(e){if(serial===requestSerial)$('#txTable').innerHTML=errorHtml(e);}
    };
    $('#txSearch').oninput=e=>{txListState.q=e.target.value;txListState.page=1;clearTimeout(searchTimer);searchTimer=setTimeout(loadPage,250);};
    $('#txStatus').onchange=e=>{txListState.status=e.target.value;txListState.page=1;loadPage();};
    $('#txMonth').onchange=e=>{txListState.month=e.target.value;txListState.page=1;loadPage();};
    $('#txPerPage').onchange=e=>{txListState.per_page=Number(e.target.value)||50;txListState.page=1;loadPage();};
    loadPage();
  }

  function historyFor(id){return [...(historyCache.get(id)||[])].sort((a,b)=>Number(b.revision)-Number(a.revision));}
  function eventLabel(type){return ({draft_created:'Draft created',draft_edit:'Draft recalculated',draft_deleted:'Draft cancelled',draft_cancelled:'Draft cancelled',returned_to_draft:'Returned to Draft for editing',submitted_revision_draft:'Submitted revision Draft created',submitted_revision_discarded:'Revision Draft discarded',returned_for_correction:'Returned for correction',returned_correction_edit:'Correction revised',correction_resubmitted:'Correction resubmitted',submitted:'Submitted',edit:'Edited while submitted',edit_requested:'Edit submitted for approval',edit_request_updated:'Pending edit revised',edit_request_cancelled:'Pending edit cancelled',checked:'Checked by Division',division_checked:'Division transaction checked',checked_edit_approved:'Pending edit approved by Division',edit_request_discarded:'Pending edit discarded',deletion_requested:'Cancellation requested',deletion_approved:'Cancellation approved',deletion_rejected:'Cancellation rejected',cancellation_requested:'Cancellation requested',cancellation_approved:'Cancellation approved',cancellation_rejected:'Cancellation rejected',division_checked_deleted:'Division checked transaction cancelled',void:'Voided',baseline:'Existing record baseline'})[type]||String(type||'').replaceAll('_',' ');}
  function historyChanges(row){const a=row.before_data||{},b=row.after_data||{},items=[];if(a.supplier_id!==undefined&&a.supplier_id!==b.supplier_id)items.push(`Supplier: ${supplierName(a.supplier_id)} → ${supplierName(b.supplier_id)}`);if(a.transaction_type!==undefined&&a.transaction_type!==b.transaction_type)items.push(`Transaction type: ${shortTransactionType(a.transaction_type)||'—'} → ${shortTransactionType(b.transaction_type)||'—'}`);if(a.source_fund_id!==undefined&&a.source_fund_id!==b.source_fund_id)items.push(`Source of Fund: ${sourceFundName(a.source_fund_id)} → ${sourceFundName(b.source_fund_id)}`);if(a.date!==undefined&&a.date!==b.date)items.push(`Date: ${a.date||'—'} → ${b.date||'—'}`);if(a.gross!==undefined&&Number(a.gross)!==Number(b.gross))items.push(`Gross: ${money(a.gross)} → ${money(b.gross)}`);if(a.status!==undefined&&a.status!==b.status)items.push(`Status: ${statusText(a.status)||'—'} → ${statusText(b.status)||'—'}`);return items.length?`<ul class="history-changes">${items.map(x=>`<li>${h(x)}</li>`).join('')}</ul>`:'';}
  function historyMarkup(id){const rows=historyFor(id);if(!rows.length)return '<div class="empty compact">No edit history recorded yet.</div>';return `<div class="history-list">${rows.map(r=>`<div class="history-item"><div class="history-head"><strong>Revision ${h(r.revision)} · ${h(eventLabel(r.event_type))}</strong><span>${h(fmtDateTime(r.at))}</span></div><div class="master-meta">${h(r.actor_email||r.actor||'System')} · ${h(roleLabel(r.actor_role)||r.actor_role)}</div>${historyChanges(r)}${r.remarks?`<div class="history-remarks"><strong>Remarks:</strong> ${h(r.remarks)}</div>`:''}</div>`).join('')}</div>`;}
  async function loadTransactionEditor(t){try{t=await fetchTransaction(t.id);}catch(e){toast(e.message,'error');return;}const p=t.status==='checked'&&t.pending_edit?t.pending_edit:null,srcRow=p||t;draft={id:t.id,date:srcRow.date,amount:(Number(srcRow.gross)/100).toFixed(2),transaction_scope:transactionScope(t),school_id:t.school_id||'',supplier_id:srcRow.supplier_id,transaction_type:transactionTypeForRow(srcRow)||transactionTypeForRow(t),source_fund_id:srcRow.source_fund_id||''};review=null;try{if(['draft','submitted','returned'].includes(t.status))review=await api({action:'preview',id:t.id});else if(p)review=await api({action:'previewPending',id:t.id});else if(t.status==='checked'&&t.snapshot)review={snapshot:t.snapshot};}catch(e){toast(e.message,'error');}modal.close();renderGenerate();}

  async function openTransaction(id){
    let t;try{const loaded=await Promise.all([fetchTransaction(id),fetchHistory(id,true)]);t=loaded[0];}catch(e){toast(e.message,'error');return;}
    const scope=transactionScope(t),origin=transactionOriginName(t);
    let currentPreview=null,pendingPreview=null;
    if(['draft','submitted','returned'].includes(t.status)){try{currentPreview=await api({action:'preview',id:t.id});}catch(e){currentPreview={error:e.message};}}
    if(scope==='school'&&t.status==='checked'&&t.pending_edit){try{pendingPreview=await api({action:'previewPending',id:t.id});}catch(e){pendingPreview={error:e.message};}}
    const s=['draft','submitted','returned'].includes(t.status)?currentPreview?.snapshot:t.snapshot, fund=s?.source_fund?.name||sourceFundName(t.source_fund_id), amounts=s?.amounts;
    const rep=s?.representative||{name:s?.school?.representative||'',position:s?.school?.position||'',tin:s?.school?.representative_tin||''};
    const pending=scope==='school'?t.pending_edit:null,ps=pendingPreview?.snapshot,pa=ps?.amounts;
    const deletionRequest=t.deletion_request||null;
    const pendingSection=pending?`<section class="pending-review"><div class="panel-head"><div><div class="kicker">Pending school edit</div><h3>${h(ps?.supplier?.name||supplierName(pending.supplier_id))}</h3>${ps?`<div class="master-meta">${h(supplierTaxStatus(ps.supplier?.vat_status)||'—')} · TIN ${h(formatSupplierTin(ps.supplier?.tin)||'—')}</div>`:''}</div><span class="status pending">pending approval</span></div>${pendingPreview?.error?`<div class="notice error">${h(pendingPreview.error)}</div>`:`<p class="muted">${h(pending.date)} · Submitted ${h(fmtDateTime(pending.submitted_at))}</p><div class="notice"><strong>Proposed Source of Fund:</strong> ${h(ps?.source_fund?.name||sourceFundName(pending.source_fund_id))}<br><strong>Proposed transaction type:</strong> ${h(shortTransactionType(ps?.transaction_type||ps?.supplier?.transaction_type||transactionTypeForRow(pending))||'—')}</div>${ps?snapshotEncodingDetailsHtml(ps):''}<div class="review"><div class="review-row"><span>Proposed gross amount</span><strong>${money(pending.gross)}</strong></div>${pa?`<div class="review-row"><span>Tax base</span><strong>${money(pa.base)}</strong></div><div class="review-row"><span>VAT withheld · ${h(ps?.business?.name||'—')} (${h(ps?.business?.rate??'—')}%)</span><strong>${money(pa.business)}</strong></div><div class="review-row"><span>Expanded withholding · ${h(ps?.ewt?.name||'—')} (${h(ps?.ewt?.rate??'—')}%)</span><strong>${money(pa.ewt)}</strong></div><div class="review-row"><span>Total withheld</span><strong>${money(pa.total)}</strong></div><div class="review-row"><span>Net payment</span><strong>${money(pa.net)}</strong></div>`:''}</div>`}<div class="notice warn"><strong>The last checked version remains official.</strong> These proposed changes do not replace it until a Division user approves them.</div></section>`:'';
    const canReview=!deletionRequest&&scope==='school'&&isAdmin()&&(t.status==='submitted'||(t.status==='checked'&&pending));
    const canReturn=!deletionRequest&&scope==='school'&&isAdmin()&&['submitted','checked'].includes(t.status);
    const reviewAction=(canReview||canReturn)?`<section class="review-action"><h3>${t.status==='submitted'?'Division review':(pending?'Division approval of pending edit':'Division review')}</h3><label>Remarks<textarea id="checkRemarks" maxlength="1000" placeholder="${canReturn?'Required when returning for correction; optional when checking/approving.':'Optional review remarks'}"></textarea></label><div class="actions">${canReview?`<button class="primary" id="checkTx" ${(t.status==='submitted'&&currentPreview?.error)||(pending&&pendingPreview?.error)?'disabled':''}>${t.status==='submitted'?'Mark Checked':'Approve changes'}</button>`:''}${canReturn?'<button class="secondary" id="returnTx">Return for Correction</button>':''}</div><p class="muted small">${t.status==='submitted'?'Division users review only; transaction values can be edited only by the originating school.':'Checked values remain protected. School edits still require Division approval unless the transaction is formally returned for correction.'}</p></section>`:'';
    const ownDivisionCancellationRequest=!!deletionRequest&&scope==='division'&&isAdmin()&&String(deletionRequest.requested_by||'')===String(state.actor.user_id||'');
    const canReviewCancellation=!!deletionRequest&&isAdmin()&&!ownDivisionCancellationRequest;
    const cancellationOriginLabel=scope==='division'?'Division':'School';
    const deletionRequestSection=deletionRequest?`<section class="review-action deletion-review"><div class="panel-head"><div><div class="kicker">Cancellation request</div><h3>Checked transaction cancellation</h3></div><span class="status delete-pending">awaiting Division approval</span></div><div class="notice warn"><strong>${h(cancellationOriginLabel)} reason:</strong> ${h(deletionRequest.reason||'—')}<br><span class="muted small">Requested ${h(fmtDateTime(deletionRequest.requested_at))}</span></div>${canReviewCancellation?`<label>Division remarks<textarea id="cancelReviewRemarks" maxlength="500" placeholder="Optional when approving; required when rejecting."></textarea></label><div class="actions"><button class="danger-btn" id="approveCancelRequest">Approve cancellation</button><button class="secondary" id="rejectCancelRequest">Reject request</button></div>`:(ownDivisionCancellationRequest?'<p class="muted small">Another Division-level user must approve or reject this request. Self-approval is not allowed.</p>':'<p class="muted small">The Checked transaction remains official until the Division approves this request.</p>')}</section>`:'';
    const divisionDraftAction=scope==='division'&&isAdmin()&&t.status==='draft'?`<section class="review-action"><h3>Division transaction review</h3><div class="notice"><strong>2307 representative:</strong> ${h(rep.name||state.division?.representative||'—')}<br><span class="muted">${h(rep.position||state.division?.designation||'—')}${(rep.tin||state.division?.representative_tin)?` · TIN ${h(formatSupplierTin(rep.tin||state.division?.representative_tin)||rep.tin||state.division?.representative_tin)}`:''}</span></div><div class="actions"><button class="primary" id="checkDivisionTx" ${currentPreview?.error?'disabled':''}>Mark Checked</button></div><p class="muted small">Division-level transactions are finalized directly by the Division and do not enter a school submission queue.</p></section>`:'';
    const returnedEvent=t.status==='returned'?historyFor(t.id).find(x=>x.event_type==='returned_for_correction'):null;
    const checkedNotice=t.status==='checked'?`<div class="notice success"><strong>Checked:</strong> ${h(fmtDateTime(t.finalized_at))}${s?.check_remarks?`<br><strong>Division remarks:</strong> ${h(s.check_remarks)}`:''}</div>`:'';
    const returnedNotice=t.status==='returned'?`<div class="notice warn"><strong>Returned for Correction.</strong>${returnedEvent?.remarks?`<br><strong>Division remarks:</strong> ${h(returnedEvent.remarks)}`:''}</div>`:'';
    const approvedLabel=t.status==='checked'&&pending?'<div class="kicker">Current checked / official version</div>':'';
    const canEditTransaction=!deletionRequest&&(scope==='division'?(isAdmin()&&t.status==='draft'):((t.status==='draft'&&(!t.submitted_backup||state.actor.role==='school_user'))||(['submitted','returned','checked'].includes(t.status)&&state.actor.role==='school_user')));
    const editButton=canEditTransaction?`<button class="secondary" id="editTx">${t.status==='checked'&&pending?'Edit pending changes':'Edit transaction'}</button>`:'';
    const pdfButton=['submitted','checked','void'].includes(t.status)?`<button class="primary" id="downloadPdf">${t.status==='submitted'?'Print Form 2307':(t.status==='checked'&&pending?'Download last checked Form 2307':'Download Form 2307')}</button>`:'';
    const schoolOwnsTransaction=scope==='school'&&state.actor.role==='school_user'&&String(t.created_by||'')===String(state.actor.user_id||'');
    const cancelDraftButton=t.status==='draft'&&!t.submitted_backup&&((scope==='school'&&schoolOwnsTransaction)||(scope==='division'&&isAdmin()))?'<button class="danger-btn" id="cancelDraftTx">Cancel Draft</button>':'';
    const canRequestCancellation=t.status==='checked'&&!pending&&!deletionRequest&&((scope==='school'&&schoolOwnsTransaction)||(scope==='division'&&isAdmin()));
    const requestCancelButton=canRequestCancellation?'<button class="danger-btn" id="requestCancelTx">Request cancellation</button>':'';
    const cancelledNotice=t.status==='deleted'?`<div class="notice error"><strong>Cancelled:</strong> ${h(fmtDateTime(t.deleted_at))}<br><strong>Reason:</strong> ${h(t.deletion_reason||'—')}<br><span class="muted small">This soft-cancelled record is retained for audit history and is excluded from normal transaction lists, reports, totals, duplicate checks and Form 2307 actions.</span></div>`:'';
    openModal('Transaction details',transactionReference(t),`<div class="actions compact-actions">${transactionBadges(t)}</div>${approvedLabel}<h2>${h(s?.supplier?.name||supplierName(t.supplier_id))}</h2>${s?`<div class="master-meta">${h(supplierTaxStatus(s.supplier?.vat_status)||'—')} · TIN ${h(formatSupplierTin(s.supplier?.tin)||'—')}</div>`:''}<p class="muted"><strong>Ref ${h(transactionReference(t))}</strong> · ${h(t.date)} · ${h(origin)}</p><div class="notice"><strong>Origin:</strong> ${h(origin)}<br><strong>Source of Fund:</strong> ${h(fund)}<br><strong>Transaction type:</strong> ${h(shortTransactionType(s?.transaction_type||s?.supplier?.transaction_type||transactionTypeForRow(t))||'—')}</div>${s?snapshotEncodingDetailsHtml(s):''}${currentPreview?.error?`<div class="notice error">${h(currentPreview.error)}</div>`:''}<div class="review"><div class="review-row"><span>Gross amount</span><strong>${money(t.gross)}</strong></div>${amounts?`<div class="review-row"><span>Tax base</span><strong>${money(amounts.base)}</strong></div><div class="review-row"><span>VAT withheld · ${h(s?.business?.name||'—')} (${h(s?.business?.rate??'—')}%)</span><strong>${money(amounts.business)}</strong></div><div class="review-row"><span>Expanded withholding · ${h(s?.ewt?.name||'—')} (${h(s?.ewt?.rate??'—')}%)</span><strong>${money(amounts.ewt)}</strong></div><div class="review-row"><span>Total withheld</span><strong>${money(amounts.total)}</strong></div><div class="review-row"><span>Net payment</span><strong>${money(amounts.net)}</strong></div>`:''}</div>${s?`<h3>Official payor</h3><p class="muted">${h(s.division.name)}<br>${h(formatSupplierTin(s.division.tin)||s.division.tin)}<br>${h(s.division.address)}</p><div class="notice"><strong>2307 representative:</strong> ${h(rep.name||'—')}<br><span class="muted">${h(rep.position||'—')}${rep.tin?` · TIN ${h(formatSupplierTin(rep.tin)||rep.tin)}`:''}</span></div>`:''}${checkedNotice}${returnedNotice}${cancelledNotice}${t.void_reason?`<div class="notice error">Void reason: ${h(t.void_reason)}</div>`:''}${pendingSection}${deletionRequestSection}${reviewAction}${divisionDraftAction}<section class="history-section"><h3>Edit and review history</h3>${historyMarkup(t.id)}</section><div class="actions">${editButton}${pdfButton}${cancelDraftButton}${requestCancelButton}${isAdmin()&&t.status==='checked'&&!deletionRequest?'<button class="danger-btn" id="voidTx">Void transaction</button>':''}</div>${scope==='school'&&t.status==='checked'&&state.actor.role==='school_user'?`<p class="muted small">${deletionRequest?'Cancellation is awaiting Division approval; editing is temporarily locked.':(pending?'You can revise the pending edit while it awaits approval.':'Any edit will be submitted for Division approval; the current checked version remains official until approval.')}</p>`:''}${scope==='school'&&t.status==='returned'&&state.actor.role==='school_user'?'<p class="muted small">Only your school can correct this returned transaction. Resubmit it when the requested revision is complete.</p>':''}`);
    if($('#editTx'))$('#editTx').onclick=()=>loadTransactionEditor(t);
    if($('#checkTx'))$('#checkTx').onclick=async()=>{const approving=t.status==='checked'&&pending;if(!confirm(approving?'Approve these pending changes and replace the current checked values?':'Mark this submitted transaction as Checked?'))return;try{await mutate({action:'check',id:t.id,version:t.version,pending_version:pending?.version,remarks:$('#checkRemarks').value},approving?'Pending changes approved and checked.':'Transaction marked Checked.');modal.close();renderTransactions();}catch{}};
    if($('#checkDivisionTx'))$('#checkDivisionTx').onclick=async()=>{if(!confirm('Mark this Division-level transaction as Checked? The calculation and Division representative data will be frozen for Form 2307.'))return;try{const payload={action:'check',id:t.id,version:t.version,remarks:''};let result=await api(payload);if(result?.duplicate_warning){if(!confirm(duplicateConfirmationText(result.duplicates)))return;result=await api({...payload,duplicate_confirmed:true});}await load();modal.close();renderTransactions();toast(result?.duplicate_warning_acknowledged?'Division transaction checked. Possible duplicate warning was acknowledged and recorded.':'Division transaction marked Checked.');}catch(e){toast(e.message,'error');}};
    if($('#returnTx'))$('#returnTx').onclick=async()=>{const remarks=$('#checkRemarks').value.trim();if(!remarks){toast('Enter the suggested correction in Remarks before returning the transaction.','error');$('#checkRemarks').focus();return;}if(!confirm('Return this transaction to the school for correction?'))return;try{await mutate({action:'returnForCorrection',id:t.id,version:t.version,remarks},'Transaction returned to the school for correction.');modal.close();renderTransactions();}catch{}};
    if($('#downloadPdf'))$('#downloadPdf').onclick=()=>{const action=t.status==='submitted'?printCertificate(t):downloadCertificate(t);action.catch(e=>toast(e.message,'error'));};
    if($('#voidTx'))$('#voidTx').onclick=async()=>{const reason=prompt(`Reason for voiding this checked transaction:${pending?' Pending school changes will also be discarded.':''}`);if(!reason?.trim())return;try{await mutate({action:'void',id:t.id,reason:reason.trim()},'Transaction voided with audit record.');modal.close();renderTransactions();}catch{}};
    if($('#cancelDraftTx'))$('#cancelDraftTx').onclick=async()=>{if(!confirm('Cancel this Draft? It will disappear from normal transaction lists but remain available under the Cancelled filter for audit history.'))return;try{await mutate({action:'cancelDraft',id:t.id,version:t.version},'Draft cancelled with audit history retained.');modal.close();renderTransactions();}catch{}};
    if($('#requestCancelTx'))$('#requestCancelTx').onclick=async()=>{const reason=prompt('Reason for requesting cancellation of this Checked transaction:');if(!reason?.trim())return;const approvalText=scope==='division'?'another Division-level user':'the Division';if(!confirm(`Submit this cancellation request for approval by ${approvalText}? The Checked transaction will remain official until approval.`))return;try{await mutate({action:'requestCancellation',id:t.id,version:t.version,reason:reason.trim()},scope==='division'?'Cancellation request submitted. Another Division-level user must review it.':'Cancellation request submitted to the Division.');modal.close();renderTransactions();}catch{}};
    if($('#approveCancelRequest'))$('#approveCancelRequest').onclick=async()=>{const remarks=$('#cancelReviewRemarks')?.value.trim()||'';if(!confirm('Approve this cancellation request? The transaction will be excluded from active lists and reports but retained permanently in audit history.'))return;try{await mutate({action:'approveCancellation',id:t.id,version:t.version,remarks},'Cancellation approved. The transaction was moved to Cancelled records.');modal.close();renderTransactions();}catch{}};
    if($('#rejectCancelRequest'))$('#rejectCancelRequest').onclick=async()=>{const remarks=$('#cancelReviewRemarks')?.value.trim()||'';if(!remarks){toast('Enter Division remarks explaining why the cancellation request is being rejected.','error');$('#cancelReviewRemarks')?.focus();return;}if(!confirm('Reject this cancellation request and keep the Checked transaction active?'))return;try{await mutate({action:'rejectCancellation',id:t.id,remarks},'Cancellation request rejected. The Checked transaction remains active.');modal.close();renderTransactions();}catch{}};
  }

  function renderMaster(kind){const map={suppliers:['Supplier master','Supplier','name'],atcs:['ATC master','ATC','name'],schools:['Participating schools','School','name']};const [heading,singular]=map[kind];const rows=state[kind]||[];const canEdit=isAdmin()||(kind==='schools'&&!isAdmin());const canAdd=isAdmin()||(!isAdmin()&&['suppliers','atcs'].includes(kind));const sharedAddNote=!isAdmin()&&['suppliers','atcs'].includes(kind)?'<p class="muted small">School Users may add new shared records. Existing Supplier and ATC records can be edited only by the Division.</p>':'';main.innerHTML=`<section class="panel"><div class="panel-head"><div><h2>${h(heading)}</h2><p class="muted small">Checked transaction snapshots remain historical even when master data changes.</p>${sharedAddNote}</div>${canAdd?`<button class="primary" id="addMaster">Add ${h(singular)}</button>`:''}${kind==='schools'&&!isAdmin()?'<button class="primary" id="editOwnSchool">Edit representative</button>':''}</div><div class="toolbar"><label>Search<input id="masterSearch" placeholder="Search"></label></div><div id="masterTable"></div></section>`;const draw=()=>{const q=$('#masterSearch').value.toLowerCase();const f=rows.filter(r=>JSON.stringify(r).toLowerCase().includes(q));let headers='',body='';if(kind==='suppliers'){headers='<th>Supplier</th><th>TIN</th><th>Classification</th><th>Transaction profiles</th><th>Status</th><th></th>';body=f.map(r=>{const profiles=supplierProfiles(r);return `<tr><td><strong>${h(r.name)}</strong><div class="master-meta">${h(r.address||'')}</div></td><td>${h(r.tin||'')}</td><td>${h(r.business_type)}<br><span class="muted">${h(r.vat_status)}</span></td><td>${profiles.length?profiles.map(p=>`<div class="supplier-profile-summary"><strong>${h(shortTransactionType(p.transaction_type))}</strong><span class="master-meta">VAT ${h(atcWithRate(p.business_atc))} · EWT ${h(atcWithRate(p.ewt_atc))}</span></div>`).join(''):'<span class="muted">Not configured</span>'}</td><td>${active(r)?'Active':'Inactive'}</td><td>${isAdmin()?`<button class="secondary edit-master" data-id="${h(r.id)}">Edit</button>`:''}</td></tr>`;}).join('');}
      if(kind==='atcs'){headers='<th>ATC</th><th>Description</th><th>Tax type</th><th>Rate</th><th>Applicability</th><th>Effective dates</th><th>Status</th><th></th>';body=f.map(r=>`<tr><td><strong>${h(r.name)}</strong></td><td>${h(r.description)}</td><td>${h(r.tax_type)}</td><td>${h(r.rate)}%</td><td>${h(r.business_type==='All'?'Both':(r.business_type||'Both'))}<br><span class="muted">${h(r.transaction_type||'All')}</span></td><td>${h(r.effective_from)}${r.effective_to?' to '+h(r.effective_to):' onward'}</td><td>${active(r)?'Active':'Inactive'}</td><td>${isAdmin()?`<button class="secondary edit-master" data-id="${h(r.id)}">Edit</button>`:''}</td></tr>`).join('');}
      if(kind==='schools'){headers='<th>School</th><th>Code</th><th>Representative</th><th>Status</th><th></th>';body=f.map(r=>`<tr><td><strong>${h(r.name)}</strong><div class="master-meta">${h(r.address||'')}</div></td><td>${h(r.code||'')}</td><td>${h(r.representative||'')}<br><span class="muted">${h(r.position||'')}</span></td><td>${active(r)?'Active':'Inactive'}</td><td>${canEdit?`<button class="secondary edit-master" data-id="${h(r.id)}">Edit</button>`:''}</td></tr>`).join('');}
      $('#masterTable').innerHTML=f.length?`<div class="table-wrap"><table><thead><tr>${headers}</tr></thead><tbody>${body}</tbody></table></div>`:'<div class="empty">No records found.</div>';$$('.edit-master',$('#masterTable')).forEach(b=>b.onclick=()=>openMasterEditor(kind,rows.find(r=>r.id===b.dataset.id)));};$('#masterSearch').oninput=draw;draw();if($('#addMaster'))$('#addMaster').onclick=()=>openMasterEditor(kind,null);if($('#editOwnSchool'))$('#editOwnSchool').onclick=()=>openMasterEditor('schools',rows[0]);}

  function atcBusinessMatches(atc,businessType){const c=(atc?.business_type||'Both');return c==='Both'||c==='All'||c===businessType;}
  function atcTransactionMatches(atc,transactionType){const c=(atc?.transaction_type||'All');return c==='All'||c===transactionType;}
  function supplierAtcChoices(taxType,businessType,transactionType){return (state.atcs||[]).filter(x=>active(x)&&x.tax_type===taxType&&atcBusinessMatches(x,businessType)&&atcTransactionMatches(x,transactionType));}
  function supplierAtcLabel(x){const b=x.business_type==='All'?'Both':(x.business_type||'Both');return `${x.name} · ${x.rate}% · ${b}`;}
  function refreshSupplierAtcChoices(form){
    const businessType=form.elements.business_type?.value||'Individual',transactionType=form.elements.transaction_type?.value||classifications[0];
    [['business_atc','VAT'],['ewt_atc','EWT']].forEach(([name,taxType])=>{const select=form.elements[name];if(!select)return;const current=select.value;const options=supplierAtcChoices(taxType,businessType,transactionType);select.innerHTML='<option value="">Select</option>'+options.map(x=>`<option value="${h(x.id)}">${h(supplierAtcLabel(x))}</option>`).join('');if(options.some(x=>x.id===current))select.value=current;});
  }

  function supplierProfileRowsHtml(profiles,businessType){const used=new Set(profiles.map(p=>p.transaction_type));return profiles.map((p,index)=>{const vat=supplierAtcChoices('VAT',businessType,p.transaction_type),ewt=supplierAtcChoices('EWT',businessType,p.transaction_type);const typeOptions=classifications.map(type=>`<option value="${h(type)}" ${type===p.transaction_type?'selected':''} ${used.has(type)&&type!==p.transaction_type?'disabled':''}>${h(shortTransactionType(type))}</option>`).join('');const atcOptions=(items,value)=>'<option value="">Select</option>'+items.map(x=>`<option value="${h(x.id)}" ${x.id===value?'selected':''}>${h(supplierAtcLabel(x))}</option>`).join('');return `<div class="supplier-profile-row" data-profile-index="${index}"><div class="supplier-profile-head"><strong>${h(shortTransactionType(p.transaction_type)||`Profile ${index+1}`)}</strong>${profiles.length>1?`<button class="secondary supplier-profile-remove" type="button" data-profile-remove="${index}">Remove</button>`:''}</div><div class="grid3 supplier-profile-grid"><label>Transaction type<select data-profile-field="transaction_type">${typeOptions}</select></label><label>VAT ATC<select data-profile-field="business_atc" required>${atcOptions(vat,p.business_atc)}</select></label><label>Expanded withholding ATC<select data-profile-field="ewt_atc" required>${atcOptions(ewt,p.ewt_atc)}</select></label></div></div>`;}).join('');}
  function bindSupplierProfilesEditor(form,initialProfiles){let profiles=(initialProfiles&&initialProfiles.length?initialProfiles:[{transaction_type:classifications[0],business_atc:'',ewt_atc:''}]).map(p=>({...p}));const container=$('#supplierProfiles',form),add=$('#addSupplierProfile',form);const redraw=()=>{const businessType=form.elements.business_type?.value||'Individual';profiles.forEach(p=>{const vat=supplierAtcChoices('VAT',businessType,p.transaction_type),ewt=supplierAtcChoices('EWT',businessType,p.transaction_type);if(p.business_atc&&!vat.some(x=>x.id===p.business_atc))p.business_atc='';if(p.ewt_atc&&!ewt.some(x=>x.id===p.ewt_atc))p.ewt_atc='';});container.innerHTML=supplierProfileRowsHtml(profiles,businessType);$$('[data-profile-index]',container).forEach(row=>{const index=Number(row.dataset.profileIndex);$$('[data-profile-field]',row).forEach(el=>el.onchange=()=>{const field=el.dataset.profileField;profiles[index][field]=el.value;if(field==='transaction_type')redraw();});});$$('[data-profile-remove]',container).forEach(btn=>btn.onclick=()=>{profiles.splice(Number(btn.dataset.profileRemove),1);redraw();});if(add)add.disabled=profiles.length>=classifications.length;};if(add)add.onclick=()=>{const used=new Set(profiles.map(p=>p.transaction_type)),next=classifications.find(x=>!used.has(x));if(!next){toast('All supported transaction types are already configured for this supplier.','error');return;}profiles.push({transaction_type:next,business_atc:'',ewt_atc:''});redraw();};form.elements.business_type.onchange=redraw;form._supplierProfiles=()=>profiles.map(p=>({...p}));redraw();}

  // Refresh only shared suppliers after a duplicate; leave the unsaved form and transaction draft intact.
  async function showExistingSupplierConflict(form,conflict){
    const result=await apiGet({scope:'suppliers'});
    if(!Array.isArray(result.suppliers))throw Error('Supplier list could not be refreshed.');
    state.suppliers=result.suppliers;
    if(view==='Suppliers')renderMaster('suppliers');
    const supplier=state.suppliers.find(x=>x.id===conflict?.id);
    if(!supplier){toast('The existing supplier could not be located after refreshing. Reload and try again.','error');return;}
    let notice=$('#supplierDuplicateNotice',form);
    if(!notice){notice=document.createElement('div');notice.id='supplierDuplicateNotice';notice.className='span2 notice warn';form.querySelector('.actions')?.before(notice);}
    notice.innerHTML=`<strong>Supplier already registered</strong><br>
      ${h(supplier.name)} (TIN ${h(formatSupplierTin(supplier.tin))}) is already in the shared Supplier Master. No new record was created.
      <div class="master-meta">${active(supplier)?'You can use this existing supplier for your transaction.':'This supplier is inactive. Ask the Division Administrator to review its status before using it.'}</div>
      <div class="actions" style="margin-top:0.75rem">
        ${active(supplier)?'<button type="button" class="primary" id="useExistingSupplier">Use supplier for transaction</button>':''}
        <button type="button" class="secondary" id="viewExistingSupplier">View in Supplier Master</button>
      </div>`;
    const use=$('#useExistingSupplier',notice);
    if(use)use.onclick=()=>{
      // Never reuse the ID of an already saved transaction; preserve an unsaved draft's other fields.
      const nextDraft=draft.id?{date:today(),amount:'',source_fund_id:''}:{...draft};
      const profiles=supplierProfiles(supplier);
      draft={...nextDraft,id:undefined,transaction_scope:isAdmin()?'division':'school',
        school_id:isAdmin()?'':state?.actor?.school_id||'',supplier_id:supplier.id,
        transaction_type:profiles.length===1?profiles[0].transaction_type:''};
      review=null;modal.close();go('Transactions');renderGenerate();
    };
    $('#viewExistingSupplier',notice).onclick=()=>{
      modal.close();go('Suppliers');
      const search=$('#masterSearch');if(search){search.value=supplier.tin;search.dispatchEvent(new Event('input'));search.focus();}
    };
  }

  function openMasterEditor(kind,existing){const defaults={suppliers:{name:'',tin:'',address:'',zip:'',business_type:'Individual',vat_status:'Non-VAT Registered',transaction_type:'Supplier of Goods',business_atc:'',ewt_atc:'',active:1},atcs:{name:'',description:'',tax_type:'EWT',rate:'',transaction_type:'All',business_type:'Both',effective_from:today(),effective_to:'',active:1},schools:{code:'',name:'',address:'',contact:'',representative:'',position:'',representative_tin:'',active:1},division:{name:'',tin:'',address:'',zip:'',contact:'',representative:'',designation:'',representative_tin:''}};const r={...defaults[kind],...(existing||{})};let fields='';if(kind==='suppliers'){const initialProfiles=supplierProfiles(r);r._profiles=initialProfiles.length?initialProfiles:[{transaction_type:r.transaction_type||classifications[0],business_atc:r.business_atc||'',ewt_atc:r.ewt_atc||''}];fields=`${inp('name','Supplier / Payee name',r.name)}${inp('tin','TIN',r.tin)}${area('address','Registered address',r.address)}${inp('zip','ZIP code',r.zip)}${sel('business_type','Business type',['Individual','Corporate'],r.business_type)}${sel('vat_status','Supplier tax status',['VAT Registered','Non-VAT Registered'],r.vat_status)}<div class="span2 supplier-profiles-editor"><div class="supplier-profiles-title"><div><strong>Transaction tax profiles</strong><div class="muted small">Add one profile for each transaction type this supplier can provide. Each profile keeps its own VAT and EWT ATCs.</div></div><button class="secondary" type="button" id="addSupplierProfile">Add transaction type</button></div><div id="supplierProfiles"></div></div>`;}
    if(kind==='atcs')fields=`${inp('name','ATC code',r.name)}${area('description','Description',r.description)}${sel('tax_type','Tax type',['VAT','EWT'],r.tax_type)}${inp('rate','Rate (%)',r.rate,'number','0.0001')}${sel('transaction_type','Transaction classification',['All',...classifications],r.transaction_type)}${sel('business_type','Business classification',['Both','Individual','Corporate'],r.business_type==='All'?'Both':r.business_type)}${inp('effective_from','Effective from',r.effective_from,'date')}${inp('effective_to','Effective to (optional)',r.effective_to,'date',null,false)}`;
    if(kind==='schools'){const lock=!isAdmin();fields=`${inp('code','School code',r.code,'text',null,true,lock)}${inp('name','School name',r.name,'text',null,true,lock)}${area('address','School address',r.address,true,lock)}${inp('contact','Contact (optional)',r.contact||'','text',null,false)}${inp('representative','Authorized representative',r.representative)}${inp('position','Position',r.position)}${inp('representative_tin','Representative TIN (optional)',r.representative_tin||'','text',null,false)}${!existing&&isAdmin()?`<div class="span2 notice"><strong>School account will be created automatically.</strong><br><span class="muted small">Username: the School Code · Temporary password: unique, securely generated and displayed once after saving · The user must set a new password and recovery email on first sign-in.</span></div>`:''}`;}
    if(kind==='division'){const currentLogo=r.logo_path?`logo.php${r.logo_updated_at?`?v=${encodeURIComponent(r.logo_updated_at)}`:''}`:'';fields=`${inp('name','Registered payor name',r.name)}${inp('tin','Division Office TIN',r.tin)}${area('address','Registered address',r.address)}${inp('zip','ZIP code',r.zip)}${inp('contact','Contact (optional)',r.contact||'','text',null,false)}${inp('representative','Authorized representative',r.representative||'')}${inp('designation','Designation',r.designation||'')}${inp('representative_tin','Representative TIN',r.representative_tin||'')}<div class="span2 notice"><strong>Form 2307 representative</strong><br><span class="muted small">These Division representative details are used when the Division Office creates its own transaction. School-origin transactions continue using the school representative saved in the School profile.</span></div><div class="span2"><span class="muted small">Division logo</span><div class="logo-picker-preview">${currentLogo?`<img src="${h(currentLogo)}" alt="Current division logo">`:'<div class="brand-mark" style="margin:0">WT</div>'}<div class="meta"><strong>${currentLogo?'Current logo ready':'No logo uploaded yet'}</strong><span class="muted small">Used in the sidebar/header branding and on the login page.</span></div></div></div><label class="span2"><span>Upload new logo (optional)</span><input type="file" name="logo_file" accept="image/png,image/jpeg,image/webp"><small class="muted">Recommended: square PNG/JPG/WEBP image, up to 800 KB.</small></label><label class="span2 check-inline"><input type="checkbox" name="remove_logo" value="1"> Remove current division logo</label>`;}
    const activeField=kind!=='division'&&isAdmin()?`<label class="span2"><span>Record status</span><select name="active"><option value="1" ${active(r)?'selected':''}>Active</option><option value="0" ${!active(r)?'selected':''}>Inactive</option></select></label>`:'';openModal((existing?'Edit ':'Add ')+(kind==='atcs'?'ATC':kind==='schools'?'school':kind==='division'?'Division profile':'supplier'),'Changes apply to new Draft transactions and future approved edits. Existing checked snapshots remain unchanged until a pending edit is approved by the Division.',`<form id="masterForm" class="grid2">${fields}${activeField}<div class="span2 actions"><button class="primary" type="submit">Save changes</button><button class="secondary" type="button" id="cancelModal">Cancel</button></div></form>`);$('#cancelModal').onclick=()=>modal.close();if(kind==='suppliers'){const form=$('#masterForm');bindSupplierProfilesEditor(form,r._profiles||[]);}$('#masterForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);const o=Object.fromEntries(fd.entries());delete o.logo_file;if(kind==='suppliers')o.transaction_profiles=e.target._supplierProfiles?e.target._supplierProfiles():[];if(kind==='atcs')o.rate=Number(o.rate);if(activeField)o.active=Number(o.active);if(kind==='division'){const file=fd.get('logo_file');o.remove_logo=fd.get('remove_logo')?'1':'';if(file&&file.name){if(file.size>800*1024){toast('Division logo must be 800 KB or smaller.','error');return;}o.logo_data_url=await readFileAsDataUrl(file);}}if(existing){o.id=existing.id;o.version=existing.version;}try{const res=await mutate({action:'saveMaster',kind,record:o},'Record saved.');modal.close();render();if(res?.default_account){openModal('School account created','Give these temporary credentials to the authorized school user. The password must be changed on first sign-in.',`<div class="review"><div class="review-row"><span>Username</span><strong>${h(res.default_account.username)}</strong></div><div class="review-row"><span>Temporary password</span><strong>${h(res.default_account.temporary_password)}</strong></div></div><div class="notice warn">The user will be required to set a new password and valid recovery email before entering the system.</div><div class="actions"><button class="primary" type="button" id="schoolAccountDone">Done</button></div>`);$('#schoolAccountDone').onclick=()=>modal.close();}}catch(err){if(kind==='suppliers'&&!existing&&err.code==='SUPPLIER_TIN_EXISTS'){try{await showExistingSupplierConflict(e.target,err.supplier);}catch(refreshErr){toast('Unable to refresh the shared Supplier Master. Reload and try again.','error');}}}};}

  function inp(name,label,value,type='text',step=null,required=true,disabled=false){return `<label>${h(label)}<input name="${h(name)}" type="${h(type)}" value="${h(value??'')}" ${step?`step="${h(step)}"`:''} ${required?'required':''} ${disabled?'disabled':''}></label>`;}
  function area(name,label,value,required=true,disabled=false){return `<label class="span2">${h(label)}<textarea name="${h(name)}" ${required?'required':''} ${disabled?'disabled':''}>${h(value??'')}</textarea></label>`;}
  function sel(name,label,options,value){return `<label>${h(label)}<select name="${h(name)}" required>${options.map(x=>`<option value="${h(x)}" ${x===value?'selected':''}>${h(x)}</option>`).join('')}</select></label>`;}
  function selObj(name,label,options,labelFn,value){return `<label>${h(label)}<select name="${h(name)}" required><option value="">Select</option>${options.map(x=>`<option value="${h(x.id)}" ${x.id===value?'selected':''}>${h(labelFn(x))}</option>`).join('')}</select></label>`;}

  function renderReports(){
    const fundOptions=(state.source_funds||[]).map(f=>`<option value="${h(f.id)}">${h(f.name)}</option>`).join('');
    const originOptions=isAdmin()?`<option value="all">All origins</option><option value="division">${h(state.division?.name||'Division Office')}</option><option value="__all_schools__">All Schools</option>${state.schools.map(s=>`<option value="${h(s.id)}">${h(s.name)}</option>`).join('')}`:'';
    // Distinct ATC codes from master, including inactive ones (for historic records).
    // Filter by tax type and code, not by a mutable master-record ID.
    const seenAtc=new Set();
    const atcOptions=(state.atcs||[]).filter(a=>a.name&&['VAT','EWT'].includes(a.tax_type)).map(a=>({value:`${a.tax_type}|${a.name}`,label:`${a.name} (${a.tax_type})`})).filter(a=>{if(seenAtc.has(a.value))return false;seenAtc.add(a.value);return true;}).sort((a,b)=>a.label.localeCompare(b.label)).map(a=>`<option value="${h(a.value)}">${h(a.label)}</option>`).join('');
    const atcSelection=()=>{const selected=$('#repAtc')?.value||'all';if(selected==='all')return null;const sep=selected.indexOf('|');return sep===-1?null:{type:selected.slice(0,sep),code:selected.slice(sep+1)};};
    const atcOf=(t,type)=>t.report_atcs?.[type]||t.snapshot?.[type==='VAT'?'business':'ewt']?.name||'—';
    const selectedAtcAmount=(t,a)=>{const choice=atcSelection();if(!choice||!a||atcOf(t,choice.type)!==choice.code)return null;return choice.type==='VAT'?a.business:a.ewt;};
    main.innerHTML=`<section class="panel"><div class="panel-head"><h2>Withholding report</h2><div class="actions"><button class="secondary" id="printReport" disabled>Print Report</button><button class="secondary" id="exportCsv" disabled>Export CSV</button>${isAdmin()?'<button class="secondary" id="openReconciliation" type="button">Month-End Reconciliation</button>':''}</div></div><div class="toolbar"><label>Month<input id="repMonth" type="month"></label>${isAdmin()?`<label>Origin<select id="repSchool">${originOptions}</select></label>`:''}<label>Supplier<select id="repSupplier"><option value="all">All suppliers</option>${state.suppliers.map(s=>`<option value="${h(s.id)}">${h(s.name)}</option>`).join('')}</select></label><label>Source of Fund<select id="repFund"><option value="all">All sources</option>${fundOptions}</select></label><label>ATC Code<select id="repAtc"><option value="all">All ATC codes</option>${atcOptions}</select></label><label>Status<select id="repStatus"><option value="all">All statuses</option><option value="draft">draft</option><option value="checked">checked</option><option value="pending">pending approval</option><option value="submitted">submitted</option><option value="returned">returned for correction</option><option value="void">void</option></select></label></div><div id="repBody"><div class="loading">Loading report…</div></div></section>${isAdmin()?'<section class="panel" id="reconPanel" hidden><div class="panel-head"><div><h2>Month-End Reconciliation</h2><p class="muted small">Read-only totals from Checked snapshots, monthly period states, and unresolved work. No transaction or month status is changed.</p></div><button class="secondary" type="button" id="refreshReconciliation">Refresh</button></div><div id="reconBody"></div></section>':''}`;
    let reportPage=1;
    let requestSerial=0;
    let reconciliationSerial=0;
    const loadReconciliation=async()=>{
      if(!isAdmin()||!$('#reconPanel')||$('#reconPanel').hidden)return;
      const serial=++reconciliationSerial;
      const month=$('#repMonth')?.value||today().slice(0,7),origin=$('#repSchool')?.value||'all';
      const body=$('#reconBody');body.innerHTML='<div class="loading">Loading month-end summary…</div>';
      try{
        const data=await apiGet({scope:'reconciliation',month,school:origin});
        if(serial!==reconciliationSerial||view!=='Reports'||!$('#reconBody'))return;
        const rows=data.rows||[],s=data.totals||{};
        const stateLabel=v=>({open:'Open',reopened:'Reopened',closed:'Closed / Locked',not_opened:'Not Opened'})[v]||v;
        const issueTotal=r=>Number(r.exceptions||0);
        const summary=`<div class="cards report-cards"><div class="card"><div class="label">Checked gross</div><div class="value">${money(s.checked_gross||0)}</div></div><div class="card"><div class="label">VAT withheld</div><div class="value">${money(s.checked_business||0)}</div></div><div class="card"><div class="label">EWT</div><div class="value">${money(s.checked_ewt||0)}</div></div><div class="card"><div class="label">Total withheld</div><div class="value">${money(s.checked_total||0)}</div></div><div class="card"><div class="label">Net Amount Paid</div><div class="value">${money(Number(s.checked_gross||0)-Number(s.checked_total||0))}</div></div><div class="card"><div class="label">Items to review</div><div class="value">${Number(s.exceptions||0)}</div></div></div>`;
        const integrityWarnings=Number(s.checked_hash_mismatches||0)+Number(s.checked_gross_mismatches||0);
        const html=rows.map(r=>`<tr><td><strong>${h(r.name)}</strong></td><td>${h(stateLabel(r.period_state))}</td><td>${Number(r.checked_count||0)}</td><td>${money(r.checked_gross||0)}</td><td>${money(r.checked_business||0)}</td><td>${money(r.checked_ewt||0)}</td><td><strong>${money(r.checked_total||0)}</strong></td><td><strong>${money(Number(r.checked_gross||0)-Number(r.checked_total||0))}</strong></td><td>${Number(r.void_count||0)}</td><td>${Number(r.cancelled_count||0)}</td><td><strong>${issueTotal(r)}</strong><div class="master-meta">Draft ${Number(r.draft_count||0)} · Submitted ${Number(r.submitted_count||0)} · Returned ${Number(r.returned_count||0)} · Edits ${Number(r.pending_edits||0)} · Cancellations ${Number(r.pending_cancellations||0)} · Revisions ${Number(r.revision_backups||0)} · Missing saved amounts ${Number(r.missing_checked_amounts||0)} · Integrity alerts ${Number(r.checked_hash_mismatches||0)} · Gross mismatches ${Number(r.checked_gross_mismatches||0)}</div></td></tr>`).join('');
        body.innerHTML=`<p class="muted small">${h(data.label)} · ${rows.length} target${rows.length===1?'':'s'}. This view uses the Month and Origin selectors only (not the Supplier, Fund, ATC, or Status filters). Amounts come from Checked transactions only; Void and Cancelled are shown separately. Net Amount Paid is computed as Checked gross less Total Tax Withheld, not a confirmation of cash disbursement. Exception counts are for review, not a substitute for the existing closing safeguards.</p>${integrityWarnings?`<div class="notice warn"><strong>Integrity warning:</strong> ${integrityWarnings} Checked record(s) have integrity or gross-amount mismatches. Financial amounts require review before use.</div>`:''}${summary}<div class="table-wrap"><table><thead><tr><th>Origin</th><th>Period</th><th>Checked</th><th>Checked gross</th><th>VAT</th><th>EWT</th><th>Total Tax Withheld</th><th>Net Amount Paid</th><th>Void</th><th>Cancelled</th><th>Items to review</th></tr></thead><tbody>${html||'<tr><td colspan="11">No targets found.</td></tr>'}</tbody></table></div><div class="actions" style="margin-top:1rem"><button class="secondary" id="reconPeriods" type="button">Open Transaction Periods</button></div>`;
        const open=$('#reconPeriods');if(open)open.onclick=()=>{periodPageMonth=month;go('Transaction Periods');};
      }catch(e){if(serial===reconciliationSerial&&$('#reconBody'))$('#reconBody').innerHTML=errorHtml(e);}
    };
    if(isAdmin()){
      $('#openReconciliation').onclick=()=>{const panel=$('#reconPanel');panel.hidden=!panel.hidden;$('#openReconciliation').textContent=panel.hidden?'Month-End Reconciliation':'Hide Month-End Reconciliation';if(!panel.hidden)loadReconciliation();};
      $('#refreshReconciliation').onclick=loadReconciliation;
    }
    const filterValues=()=>({month:$('#repMonth').value,school:isAdmin()?$('#repSchool').value:'all',supplier:$('#repSupplier').value,fund:$('#repFund').value,status:$('#repStatus').value,atc:$('#repAtc').value});
    const draw=()=>{const f=reportState.rows||[],sum=reportState.summary||{};$('#repBody').innerHTML=`${reportState.truncated?'<div class="notice warn"><strong>Report exceeds the 5,000-row preview limit.</strong> Refine the filters to print, or use Export CSV to download all matching rows securely from the server.</div>':''}<div class="cards report-cards"><div class="card"><div class="label">Rows</div><div class="value">${Number(reportState.total||0)}</div></div><div class="card"><div class="label">Checked gross</div><div class="value">${money(sum.gross||0)}</div></div><div class="card"><div class="label">VAT withheld</div><div class="value">${money(sum.business||0)}</div></div><div class="card"><div class="label">EWT</div><div class="value">${money(sum.ewt||0)}</div></div><div class="card"><div class="label">Total tax withheld</div><div class="value">${money(sum.total||0)}</div></div><div class="card"><div class="label">Net Amount Paid</div><div class="value">${money(Number(sum.gross||0)-Number(sum.total||0))}</div></div></div><p class="muted small">Net Amount Paid is computed as gross less Total Tax Withheld, not evidence of actual disbursement. Only Checked transactions contribute to financial summary amounts.</p>${atcSelection()?`<div class="notice"><strong>Selected ATC withheld (Checked only):</strong> ${money(reportState.selectedAtcWithheld||0)}. Other summary totals still cover all withholding types on matching transactions.</div>`:''}<div class="table-wrap"><table><thead><tr><th>Date</th><th>Origin</th><th>Source of Fund</th><th>Supplier</th><th>Status</th><th>VAT ATC</th><th>EWT ATC</th><th>Gross</th><th>Tax Base</th><th>VAT</th><th>EWT</th><th>Total Tax Withheld</th><th>Net Amount Paid</th></tr></thead><tbody>${f.length?f.map(t=>{const a=txAmounts(t);return `<tr><td>${h(t.date)}<div class="master-meta">Ref ${h(transactionReference(t))}</div></td><td>${h(transactionOriginName(t))}</td><td>${h(t.snapshot?.source_fund?.name||sourceFundName(t.source_fund_id))}</td><td>${supplierDisplayHtml(t)}</td><td><div class="status-stack">${transactionBadges(t)}</div></td><td>${h(atcOf(t,'VAT'))}</td><td>${h(atcOf(t,'EWT'))}</td><td>${money(t.gross)}</td><td>${a?money(a.base):'—'}</td><td>${a?money(a.business):'—'}</td><td>${a?money(a.ewt):'—'}</td><td><strong>${a?money(a.total):'—'}</strong></td><td><strong>${a?money(Number(t.gross||0)-Number(a.total||0)):'—'}</strong></td></tr>`;}).join(''):'<tr><td colspan="13"><div class="empty">No records match the selected filters.</div></td></tr>'}</tbody></table></div>`;$('#printReport').disabled=reportState.truncated;$('#exportCsv').disabled=false;
      const pages=Math.max(1,Math.ceil(Number(reportState.total||0)/100));
      $('#repBody').insertAdjacentHTML('beforeend',`<div class="panel-head compact-pager"><span class="muted small">${Number(reportState.total||0)} matching rows · Page ${reportPage} of ${pages} · showing up to 100 rows per page</span><div class="actions compact-actions"><button class="secondary" type="button" id="repPrev" ${reportPage<=1?'disabled':''}>Previous</button><button class="secondary" type="button" id="repNext" ${reportPage>=pages?'disabled':''}>Next</button></div></div>`);
      $('#repPrev').onclick=()=>{if(reportPage>1){reportPage--;loadRows();}};
      $('#repNext').onclick=()=>{if(reportPage<pages){reportPage++;loadRows();}};
    };
    const loadRows=async()=>{const serial=++requestSerial;$('#repBody').innerHTML='<div class="loading">Loading report…</div>';$('#printReport').disabled=true;$('#exportCsv').disabled=true;try{const j=await apiGet({scope:'reports',...filterValues(),page:reportPage});if(serial!==requestSerial||view!=='Reports'||!$('#repBody'))return;if(Number(j.pagination?.pages||1)<reportPage){reportPage=Math.max(1,Number(j.pagination?.pages||1));loadRows();return;}reportState.rows=cacheTransactions(j.rows||[]);reportState.summary=j.summary||{gross:0,base:0,business:0,ewt:0,total:0};reportState.total=Number(j.total||0);reportState.truncated=!!j.truncated;reportState.selectedAtcWithheld=j.selected_atc_withheld;draw();}catch(e){if(serial===requestSerial)$('#repBody').innerHTML=errorHtml(e);}};
    ['repMonth','repSchool','repSupplier','repFund','repStatus','repAtc'].forEach(id=>{const el=$('#'+id);if(el)el.onchange=()=>{reportPage=1;loadRows();if(id==='repMonth'||id==='repSchool')loadReconciliation();};});
    $('#printReport').onclick=async()=>{
      const w=window.open('','_blank','width=1200,height=800');
      if(!w){toast('Allow pop-ups for this site to print reports.','error');return;}
      w.document.write('<p style="font-family:Arial,sans-serif">Preparing complete report for printing…</p>');w.document.close();
      try {
      const full=await apiGet({scope:'reports',...filterValues(),all_rows:'1'});
      if(full.truncated)throw Error('Report exceeds the 5,000-row print limit. Refine the filters first.');
      const f=cacheTransactions(full.rows||[]),sum=full.summary||{},month=$('#repMonth').value||'All months',origin=isAdmin()?($('#repSchool').selectedOptions[0]?.textContent||'All origins'):(state.schools[0]?.name||'Assigned school'),supplier=$('#repSupplier').selectedOptions[0]?.textContent||'All suppliers',fund=$('#repFund').selectedOptions[0]?.textContent||'All sources',status=$('#repStatus').selectedOptions[0]?.textContent||'All statuses',atc=$('#repAtc').selectedOptions[0]?.textContent||'All ATC codes',division=state.division?.name||'Division Office',generated=new Date().toLocaleString('en-PH',{timeZone:'Asia/Manila'});const rows=f.map(t=>{const a=txAmounts(t);return `<tr><td>${h(t.date)}<div class="master-meta">Ref ${h(transactionReference(t))}</div></td><td>${h(transactionOriginName(t))}</td><td>${h(t.snapshot?.source_fund?.name||sourceFundName(t.source_fund_id))}</td><td>${supplierDisplayHtml(t)}</td><td>${h(transactionStatusText(t))}</td><td>${h(atcOf(t,'VAT'))}</td><td>${h(atcOf(t,'EWT'))}</td><td class="num">${money(t.gross)}</td><td class="num">${a?money(a.base):'—'}</td><td class="num">${a?money(a.business):'—'}</td><td class="num">${a?money(a.ewt):'—'}</td><td class="num"><strong>${a?money(a.total):'—'}</strong></td><td class="num"><strong>${a?money(Number(t.gross||0)-Number(a.total||0)):'—'}</strong></td></tr>`;}).join('')||'<tr><td colspan="13" class="empty">No records match the selected filters.</td></tr>';w.document.open();w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Withholding Report</title><style>@page{size:landscape;margin:10mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#111;margin:0;font-size:10px}h1{font-size:19px;margin:0 0 3px}h2{font-size:12px;margin:0;font-weight:normal}.meta{margin:12px 0;border:1px solid #aaa;padding:7px;display:grid;grid-template-columns:repeat(6,1fr);gap:5px 12px}.meta strong{display:block;font-size:8px;text-transform:uppercase}.summary{display:grid;grid-template-columns:repeat(6,1fr);gap:6px;margin:9px 0}.box{border:1px solid #aaa;padding:6px}.box span{display:block;font-size:8px;text-transform:uppercase}.box b{font-size:12px}table{width:100%;border-collapse:collapse;margin-top:9px}th,td{border:1px solid #999;padding:4px;text-align:left;vertical-align:top}th{background:#eee}.num{text-align:right;white-space:nowrap}.master-meta{font-size:8px;color:#444;margin-top:1px;white-space:nowrap}.empty{text-align:center;padding:18px}.footer{margin-top:8px;font-size:8px;color:#555}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><h1>Non-IUS Withholding Tax Monitoring</h1><h2>${h(division)} — Withholding Report</h2><div class="meta"><div><strong>Month</strong>${h(month)}</div><div><strong>Origin</strong>${h(origin)}</div><div><strong>Supplier</strong>${h(supplier)}</div><div><strong>Source of Fund</strong>${h(fund)}</div><div><strong>Status</strong>${h(status)}</div><div><strong>ATC Code</strong>${h(atc)}</div></div>${atcSelection()?`<div class="box"><span>Selected ATC Withheld (Checked only)</span><b>${money(reportState.selectedAtcWithheld||0)}</b></div>`:''}<div class="summary"><div class="box"><span>Rows</span><b>${reportState.total}</b></div><div class="box"><span>Checked Gross</span><b>${money(sum.gross||0)}</b></div><div class="box"><span>VAT Withheld</span><b>${money(sum.business||0)}</b></div><div class="box"><span>EWT</span><b>${money(sum.ewt||0)}</b></div><div class="box"><span>Total Tax Withheld</span><b>${money(sum.total||0)}</b></div><div class="box"><span>Net Amount Paid</span><b>${money(Number(sum.gross||0)-Number(sum.total||0))}</b></div></div><table><thead><tr><th>Date</th><th>Origin</th><th>Source of Fund</th><th>Supplier</th><th>Status</th><th>VAT ATC</th><th>EWT ATC</th><th>Gross</th><th>Tax Base</th><th>VAT</th><th>EWT</th><th>Total Tax Withheld</th><th>Net Amount Paid</th></tr></thead><tbody>${rows}</tbody></table><div class="footer">Generated ${h(generated)}. Financial summary totals include checked records only. Net Amount Paid means calculated gross less Total Tax Withheld and does not confirm actual disbursement. School Submitted amounts use their frozen submission snapshot, pending school edits use their frozen proposed snapshot, and checked Division-level transactions use the frozen Division representative/profile snapshot.</div><script>window.onload=()=>setTimeout(()=>window.print(),150);<\/script></body></html>`);w.document.close();}catch(e){w.document.body.textContent=e.message||'Unable to print report.';toast(e.message||'Unable to print report.','error');}};
    $('#exportCsv').onclick=()=>{
      const query=new URLSearchParams({scope:'reports_csv',...filterValues()});
      // Authenticated server streams all matching rows; avoids partial page exports.
      window.location.assign('api.php?'+query.toString());
    };
    loadRows();
  }

  function renderAdmin(){
    if(!isAdmin()){main.innerHTML='<div class="notice error">Division administrator or Project Owner access is required.</div>';return;}
    const tabs=[['division','Division Profile'],['accounts','Authorized Account'],['audit','Recent Audit'],['funds','Source of Fund']];
    main.innerHTML=`<div class="admin-tabs" role="tablist" aria-label="Administration sections">${tabs.map(([key,label])=>`<button type="button" class="admin-tab ${adminTab===key?'active':''}" data-admin-tab="${h(key)}" role="tab" aria-selected="${adminTab===key?'true':'false'}">${h(label)}</button>`).join('')}</div><div id="adminContent"></div>`;
    $$('[data-admin-tab]',main).forEach(b=>b.onclick=()=>{adminTab=b.dataset.adminTab;renderAdmin();});
    const content=$('#adminContent');
    if(adminTab==='division'){
      const d=state.division;
      content.innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Division Office payor profile</h2><p class="muted small">Official payor identity and representative information used for Division-level Form 2307 certificates.</p></div><button class="primary" id="editDivision">${d?'Edit':'Set up'} profile</button></div>${d?`<h3>${h(d.name)}</h3><p class="muted">TIN ${h(d.tin)}<br>${h(d.address)} · ${h(d.zip)}</p><div class="notice"><strong>Authorized representative:</strong> ${h(d.representative||'Not configured')}<br><strong>Designation:</strong> ${h(d.designation||'Not configured')}<br><strong>Representative TIN:</strong> ${h(d.representative_tin?formatSupplierTin(d.representative_tin):'Not configured')}</div>`:'<div class="empty">No Division Office profile yet.</div>'}</section>`;
      $('#editDivision').onclick=()=>openMasterEditor('division',d);
      return;
    }
    if(adminTab==='accounts'){
      const accountTitle=isOwner()?'Authorized accounts':'School user accounts';
      const accountHelp=isOwner()?'Project Owner can manage Division Admins and School Users.':'Division Admins can manage School Users. Each user maintains their own recovery email in My Account.';
      const resetRequests=state.password_reset_requests||[];
      const resetRows=resetRequests.length?resetRequests.map(r=>`<tr data-reset-id="${h(r.id)}"><td><strong>${h(r.username)}</strong><div class="master-meta">${h(r.email||'No recovery email')}</div></td><td>${h(roleLabel(r.role))}</td><td>${r.school_id?h(schoolName(r.school_id)):'Division'}</td><td>${h(fmtDateTime(r.requested_at))}${r.expires_at?`<div class="master-meta">Expires ${h(fmtDateTime(r.expires_at))}</div>`:''}</td><td><div class="actions compact-actions"><button class="primary approve-reset" data-id="${h(r.id)}">Approve</button><button class="secondary reject-reset" data-reset-id="${h(r.id)}">Reject</button></div></td></tr>`).join(''):`<tr><td colspan="5" class="empty">No pending password reset requests.</td></tr>`;
      content.innerHTML=`<section class="panel password-reset-panel"><div class="panel-head"><div><h2>Pending password reset requests</h2><p class="muted small">Approval restores a temporary password and forces the user to change it on the next sign-in. Each approved reset generates a new unique, unpredictable temporary password (shown once).</p></div></div><div class="table-wrap"><table><thead><tr><th>User</th><th>Role</th><th>School</th><th>Requested</th><th></th></tr></thead><tbody>${resetRows}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h2>${h(accountTitle)}</h2><p class="muted small">${h(accountHelp)} New schools automatically receive a School User account using the school code. Manually created accounts still use a username; each user maintains their own recovery email.</p></div><button class="primary" id="addMember">Add user</button></div><div class="table-wrap"><table><thead><tr><th>Username</th><th>Recovery email</th><th>Role</th><th>School</th><th>Status</th><th></th></tr></thead><tbody>${state.members.map(m=>`<tr><td><strong>${h(m.username)}</strong></td><td>${h(m.email||'Not set')}</td><td>${h(roleLabel(m.role))}</td><td>${m.school_id?h(schoolName(m.school_id)):(m.role==='school_user'?'—':'Division')}</td><td>${Number(m.active)?(Number(m.must_change_password)?'Active · password change required':'Active'):'Inactive'}</td><td><button class="secondary edit-member" data-id="${h(m.id)}">${m.id===state.actor.id?'Account':'Edit'}</button></td></tr>`).join('')}</tbody></table></div></section>`;
      $('#addMember').onclick=()=>openMemberEditor(null);
      $$('.edit-member',content).forEach(b=>b.onclick=()=>openMemberEditor(state.members.find(m=>m.id===b.dataset.id)));
      $$('.approve-reset',content).forEach(b=>b.onclick=async()=>{const req=resetRequests.find(r=>r.id===b.dataset.id);if(!req)return;if(!confirm(`Approve password reset for ${req.username}? Their current password will stop working and a temporary password will be issued.`))return;try{const result=await api({action:'approvePasswordReset',id:req.id});await load();adminTab='accounts';renderAdmin();openModal('Password reset approved','Give these temporary credentials directly to the user. They must change the password on the next sign-in.',`<div class="credential-box"><div><span>Username</span><strong>${h(result.username)}</strong></div><div><span>Temporary password</span><strong class="code-value">${h(result.temporary_password)}</strong></div></div><div class="notice warn">The temporary password is shown here for handoff because SMTP email is not configured. The user will be forced to set a new password before entering the application.</div><div class="actions"><button type="button" class="primary" id="closeResetResult">Done</button></div>`);$('#closeResetResult').onclick=()=>modal.close();}catch(e){toast(e.message,'error');}});
      $$('.reject-reset',content).forEach(b=>b.onclick=async()=>{const req=resetRequests.find(r=>r.id===b.dataset.resetId);if(!req)return;const reason=prompt(`Optional note for rejecting ${req.username}'s reset request:`,'')??null;if(reason===null)return;try{await mutate({action:'rejectPasswordReset',id:req.id,reason},'Password reset request rejected.');adminTab='accounts';renderAdmin();}catch{}});
      return;
    }
    if(adminTab==='audit'){
      content.innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Recent audit events</h2><p class="muted small">The latest 100 recorded administrative and transaction actions.</p></div></div><div class="table-wrap"><table><thead><tr><th>Time</th><th>Action</th><th>Entity</th><th>Actor</th></tr></thead><tbody>${state.audit.slice(0,100).map(a=>`<tr><td>${h(fmtDateTime(a.at))}</td><td>${h(a.action)}</td><td>${h(a.entity)}</td><td class="master-meta">${h(a.actor)}</td></tr>`).join('')}</tbody></table></div></section>`;
      return;
    }
    const funds=state.source_funds||[];
    content.innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Source of Fund</h2><p class="muted small">Configure the funding sources available when schools create withholding transactions. Inactive sources remain preserved in historical records.</p></div><button class="primary" id="addFund">Add source of fund</button></div><div class="table-wrap"><table><thead><tr><th>Source of Fund</th><th>Status</th><th></th></tr></thead><tbody>${funds.map(f=>`<tr><td><strong>${h(f.name)}</strong></td><td>${active(f)?'Active':'Inactive'}</td><td><button class="secondary edit-fund" data-id="${h(f.id)}">Edit</button></td></tr>`).join('')}</tbody></table></div></section>`;
    $('#addFund').onclick=()=>openSourceFundEditor(null);
    $$('.edit-fund',content).forEach(b=>b.onclick=()=>openSourceFundEditor(funds.find(f=>f.id===b.dataset.id)));
  }

  function openSourceFundEditor(existing){const r={name:'',active:1,...(existing||{})};openModal((existing?'Edit':'Add')+' source of fund','This list controls the mandatory Source of Fund choices available for new and edited Draft transactions.',`<form id="fundForm" class="grid2">${inp('name','Source of Fund',r.name)}<label>Record status<select name="active"><option value="1" ${active(r)?'selected':''}>Active</option><option value="0" ${!active(r)?'selected':''}>Inactive</option></select></label><div class="span2 actions"><button class="primary" type="submit">Save source of fund</button><button class="secondary" type="button" id="cancelModal">Cancel</button></div></form>`);$('#cancelModal').onclick=()=>modal.close();$('#fundForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target).entries());o.active=Number(o.active);if(existing){o.id=existing.id;o.version=existing.version;}try{await mutate({action:'saveMaster',kind:'source_funds',record:o},'Source of Fund saved.');modal.close();adminTab='funds';renderAdmin();}catch{}};}

  function openMemberEditor(existing){const r={username:'',password:'',role:'school_user',school_id:'',active:1,...(existing||{})};const self=!!existing&&existing.id===state.actor.id;const fixedPrivileged=!!existing&&(existing.role==='project_owner'||(existing.role==='division_admin'&&!isOwner()));const allowedRoles=isOwner()?['school_user','division_admin']:['school_user'];const roleField=fixedPrivileged?`<label>Role<input value="${h(roleLabel(r.role))}" disabled><input type="hidden" name="role" value="${h(r.role)}"></label>`:sel('role','Role',allowedRoles,r.role);const statusField=fixedPrivileged?`<label>Account status<input value="Active" disabled><input type="hidden" name="active" value="1"></label>`:`<label>Account status<select name="active"><option value="1" ${Number(r.active)?'selected':''}>Active</option><option value="0" ${!Number(r.active)?'selected':''}>Inactive</option></select></label>`;const usernameField=existing?`<label>Username<input value="${h(r.username)}" disabled><input type="hidden" name="username" value="${h(r.username)}"></label>`:inp('username','Username',r.username,'text',null,true);const recovery=`<label>Recovery email<input value="${h(r.email||'Not set by user')}" disabled></label>`;const desc=self?'Use My Account to maintain your recovery email and use your one-time username change.':'Create the account with an initial username and temporary password. The user must set a valid recovery email and a new password on first sign-in. Existing passwords are reset only through the approved reset workflow.';openModal((existing?'Edit':'Add')+' authorized account',desc,`<form id="memberForm" class="grid2">${usernameField}${existing?recovery:''}${existing?'':inp('password','Temporary password','', 'password',null,true)}${roleField}<label id="memberSchoolWrap">Assigned school<select name="school_id"><option value="">Select school</option>${state.schools.map(s=>`<option value="${h(s.id)}" ${s.id===r.school_id?'selected':''}>${h(s.name)}</option>`).join('')}</select></label>${statusField}<div class="span2 actions"><button class="primary" type="submit">Save account</button><button class="secondary" type="button" id="cancelModal">Cancel</button></div></form>`);const role=$('[name=role]',modal);const wrap=$('#memberSchoolWrap');const toggle=()=>wrap.style.display=role&&role.value==='school_user'?'grid':'none';if(role)role.onchange=toggle;toggle();$('#cancelModal').onclick=()=>modal.close();$('#memberForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target).entries());o.active=Number(o.active);if(existing)o.id=existing.id;try{await mutate({action:'saveMember',record:o},'Authorized account saved.');modal.close();renderAdmin();}catch{}};}

  function renderMyAccount(){const a=state.actor,used=Number(a.username_changed_once)===1;const usernameField=used?`<label class="span2">Username<input name="username" value="${h(a.username)}" disabled><input type="hidden" name="username" value="${h(a.username)}"><small class="muted">Your one-time username change has already been used.</small></label>`:`<label class="span2">Username<input name="username" value="${h(a.username)}" required autocomplete="username"><small class="muted">You may change your username once. After a successful change, it becomes locked.</small></label>`;main.innerHTML=`<section class="panel"><div class="panel-head"><div><h2>My Account</h2><p class="muted small">${used?'Your username is now locked.':'You still have one username change available.'} After adding a recovery email, either your username or that email can be used to sign in.</p></div></div><div class="review"><div class="review-row"><span>Username</span><strong>${h(a.username)}</strong></div><div class="review-row"><span>Username change</span><strong>${used?'Already used':'Available once'}</strong></div><div class="review-row"><span>Recovery email</span><strong>${h(a.email||'Not set')}</strong></div><div class="review-row"><span>Role</span><strong>${h(roleLabel(a.role))}</strong></div></div><form id="ownAccountForm" class="grid2" style="margin-top:1rem">${usernameField}<label class="span2">Recovery email<input name="email" type="email" required value="${h(a.email||'')}" placeholder="name@example.com"><small class="muted">This email must be unique. It can also be used to sign in and is reserved for password recovery.</small></label><label>Current password<input name="current_password" type="password" autocomplete="current-password" required></label><label>New password (optional)<input name="new_password" type="password" minlength="10" autocomplete="new-password"><small class="muted">Leave blank to keep your current password.</small></label><div class="span2 actions"><button class="primary" type="submit">Update my account</button></div></form></section>`;$('#ownAccountForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target).entries());const changing=!used&&String(o.username||'').trim().toLowerCase()!==String(a.username||'').toLowerCase();if(changing&&!confirm('Change your username now? This one-time username change cannot be used again after it is saved.'))return;try{await mutate({action:'updateOwnAccount',record:o},changing?'Username changed and account updated.':'Account updated.');renderMyAccount();}catch{}};}


  async function renderPeriods(){
    if(!isAdmin()){main.innerHTML='<div class="notice error">Division access is required.</div>';return;}
    main.innerHTML='<div class="loading">Loading transaction periods…</div>';
    try{
      const info=await apiGet({scope:'periods',month:periodPageMonth}),targets=info.targets||[],overview=info.overview||{},history=info.history||[],targetNames=Object.fromEntries(targets.map(t=>[t.target_key,t.name]));
      const openCount=Number(overview.open_targets||0),totalCount=Number(overview.total_targets||targets.length),closedCount=Number(overview.closed_targets||0),notOpened=Number(overview.not_opened_targets||0);
      main.innerHTML=`<div class="cards"><div class="card"><div class="label">Open / Reopened</div><div class="value">${openCount}</div></div><div class="card"><div class="label">Closed / Locked</div><div class="value">${closedCount}</div></div><div class="card"><div class="label">Not Opened</div><div class="value">${notOpened}</div></div><div class="card"><div class="label">Total targets</div><div class="value">${totalCount}</div></div></div><section class="panel"><div class="panel-head"><div><h2>${h(info.label||periodPageMonth)}</h2><p class="muted small">Select the schools and/or Division Office that may transact in this month. Closing is blocked while unfinished work remains.</p></div><label style="min-width:190px">Transaction month<input id="periodMonth" type="month" value="${h(periodPageMonth)}"></label></div><div class="actions period-selection-actions"><button class="secondary" type="button" id="periodSelectDivision">Select entire division</button><button class="secondary" type="button" id="periodSelectSchools">Select all schools</button><button class="secondary" type="button" id="periodClear">Clear selection</button></div><div class="table-wrap"><table><thead><tr><th style="width:48px">Select</th><th>Target</th><th>Current state</th><th>Last action</th></tr></thead><tbody>${targets.map(t=>`<tr><td><input class="period-check" type="checkbox" data-period-target="${h(t.target_key)}"></td><td><strong>${h(t.name)}</strong><div class="master-meta">${t.transaction_scope==='division'?'Division Office':'School'}</div></td><td>${periodStateBadge(t.state)}</td><td>${t.last_action_at?`${h(fmtDateTime(t.last_action_at))}<div class="master-meta">${h(t.last_action_by_name||'')}</div>`:'—'}</td></tr>`).join('')}</tbody></table></div><div class="actions"><button class="primary" type="button" id="periodOpen">Open selected</button><button class="secondary" type="button" id="periodClose">Close selected</button></div><div class="notice"><strong>Period rules</strong><br><span class="small">Not Opened blocks entry. Open allows transactions. Closed locks the month. Reopening a closed target requires a reason and is permanently recorded. A month cannot be closed while Draft, Submitted, Returned, pending Checked edits, or pending cancellation requests remain for that target.</span></div></section><section class="panel"><h2>Period history — ${h(info.label||periodPageMonth)}</h2>${history.length?`<div class="table-wrap"><table><thead><tr><th>Time</th><th>Target</th><th>Action</th><th>User</th><th>Reason</th></tr></thead><tbody>${history.map(r=>`<tr><td>${h(fmtDateTime(r.at))}</td><td>${h(targetNames[r.target_key]||r.target_key)}</td><td>${periodStateBadge(r.action==='reopen'?'reopened':r.action==='close'?'closed':'open')}</td><td>${h(r.actor_name||r.actor||'')}</td><td>${h(r.reason||'—')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty compact">No period actions recorded for this month yet.</div>'}</section>`;
      $('#periodMonth').onchange=e=>{periodPageMonth=e.target.value||today().slice(0,7);renderPeriods();};
      const checks=()=>$$('[data-period-target]');
      $('#periodSelectDivision').onclick=()=>checks().forEach(c=>c.checked=true);
      $('#periodSelectSchools').onclick=()=>checks().forEach(c=>c.checked=!String(c.dataset.periodTarget||'').startsWith('division'));
      $('#periodClear').onclick=()=>checks().forEach(c=>c.checked=false);
      const selected=()=>checks().filter(c=>c.checked).map(c=>c.dataset.periodTarget);
      $('#periodOpen').onclick=async()=>{const keys=selected();if(!keys.length){toast('Select at least one school or Division Office.','error');return;}const selectedRows=targets.filter(t=>keys.includes(t.target_key)),needsReason=selectedRows.some(t=>t.state==='closed');let reason='';if(needsReason){reason=prompt('Reason for reopening the selected closed transaction period(s):','')||'';if(!reason.trim()){toast('A reopening reason is required for closed periods.','error');return;}}if(!confirm(`Open ${info.label||periodPageMonth} for ${keys.length} selected target${keys.length===1?'':'s'}?`))return;try{const r=await api({action:'setTransactionPeriods',month:periodPageMonth,operation:'open',targets:keys,reason});await load();toast(`${r.changed?.length||0} period target${(r.changed?.length||0)===1?'':'s'} opened/reopened.`);}catch(e){toast(e.message,'error');}};
      $('#periodClose').onclick=async()=>{const keys=selected();if(!keys.length){toast('Select at least one school or Division Office.','error');return;}if(!confirm(`Close and lock ${info.label||periodPageMonth} for ${keys.length} selected target${keys.length===1?'':'s'}? Unfinished work will prevent closing.`))return;try{const r=await api({action:'setTransactionPeriods',month:periodPageMonth,operation:'close',targets:keys});await load();toast(`${r.changed?.length||0} period target${(r.changed?.length||0)===1?'':'s'} closed.`);}catch(e){toast(e.message,'error');}};
    }catch(e){main.innerHTML=errorHtml(e);}
  }

  async function renderSystem(){if(!isOwner()){main.innerHTML='<div class="notice error">Project Owner access is required.</div>';return;}main.innerHTML='<div class="loading">Loading system status…</div>';try{const r=await fetch('system.php',{cache:'no-store'});const info=await r.json();if(!r.ok)throw Error(info.error||'Unable to read system status.');main.innerHTML=`<div class="admin-tabs" role="tablist" aria-label="System Settings sections"><button type="button" class="admin-tab" data-settings-tab="update" role="tab" aria-controls="settingsUpdatePanel">Update</button><button type="button" class="admin-tab" data-settings-tab="sql" role="tab" aria-controls="settingsSqlPanel">SQL</button></div><div id="settingsUpdatePanel" role="tabpanel"><div class="cards"><div class="card"><div class="label">Application version</div><div class="value">v${h(info.app_version)}</div></div><div class="card"><div class="label">PHP</div><div class="value">${h(info.php_version)}</div></div><div class="card"><div class="label">Database</div><div class="value" style="font-size:1rem">${h(info.database_version)}</div></div><div class="card"><div class="label">ZIP updates</div><div class="value">${info.zip_extension?'Ready':'Unavailable'}</div></div></div><section class="panel"><div class="maintenance-grid"><div class="maintenance-card"><h2>Upload and Review Update</h2><p class="muted small">Review the release details and compatibility before choosing to install. The upload and review step does not change the application or database.</p><form id="updateForm" class="update-box"><label>Non-IUS update ZIP<input type="file" name="update" accept=".zip" required></label><div class="actions"><button class="primary" type="submit" ${info.zip_extension?'':'disabled'}>Upload and Review</button></div><p class="muted small">Hosting limits: upload_max_filesize ${h(info.upload_max_filesize)}, post_max_size ${h(info.post_max_size)}.</p><div id="updateResult" aria-live="polite"></div><div id="updateReview" hidden></div></form></div></div></section><section class="panel"><h2>Update History</h2><p class="muted small">Completed installations are recorded from v0.4.44 onward. Older audit-only entries are marked unverified because the previous updater logged them before installation finished.</p>${info.update_history?.length?`<div class="table-wrap"><table class="update-history-table"><thead><tr><th>Version</th><th>Date / Time</th><th>Installed by</th><th>Result</th><th>Release details</th></tr></thead><tbody>${info.update_history.map(u=>`<tr><td class="nowrap"><strong>v${h(u.from_version)} → v${h(u.to_version)}</strong></td><td>${h(u.at||'—')}</td><td>${h(u.actor||'Unknown')}</td><td><span class="status">${h(u.status)}</span></td><td>${u.release_details?`<details><summary>View notes</summary><pre class="update-release-notes">${h(u.release_details)}</pre></details>`:h(u.note||'Not recorded')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted small">No historical installations recorded yet. New installations will appear here.</p>'}</section><section class="panel"><h2>Login Background Pictures</h2><p class="muted small">Project Owner gallery. Upload JPG, PNG, WebP or GIF pictures (maximum 8 MB each, 8 per upload, 40 total). The system optimizes them and randomly animates them on the public sign-in page. No Google Drive or cloud account is required. Only upload pictures approved for public display.</p><div id="galleryStatus" class="muted small" aria-live="polite">Loading gallery…</div><div class="actions"><button class="secondary" id="galleryToggle" type="button" disabled>Enable or Disable Slideshow</button></div><form id="galleryUploadForm" class="update-box"><label>Upload login background pictures<input id="galleryPhotoInput" type="file" accept="image/jpeg,image/png,image/webp,image/gif" name="photos[]" multiple required></label><div class="actions"><button class="primary" type="submit">Upload Pictures</button></div></form><div id="galleryResult" aria-live="polite"></div><div id="galleryList" class="login-gallery-grid"></div></section><section class="panel"><h2>Database migrations</h2>${info.migration_integrity?.warnings?.length?`<div class="notice warn"><strong>Schema integrity needs attention:</strong><ul>${info.migration_integrity.warnings.map(w=>`<li>${h(w)}</li>`).join('')}</ul></div>`:`<div class="notice success">Basic migration and database-trigger checks found no recorded issues. Full backup restoration must still be tested separately.</div>`}<div class="table-wrap"><table><thead><tr><th>Migration</th><th>Status</th><th>Applied</th><th>Note</th></tr></thead><tbody>${info.migrations.map(m=>`<tr><td><strong>${h(m.id)}</strong><div class="master-meta">${h(m.description)}</div></td><td>${h(m.status)}</td><td>${h(m.applied_at||'—')}</td><td>${h(m.note||'')}</td></tr>`).join('')}</tbody></table></div></section></div><div id="settingsSqlPanel" role="tabpanel" hidden></div>`;
      const sqlPanel = $('#settingsSqlPanel');
      function setSettingsTab(tab) {
        settingsTab=tab==='sql'?'sql':'update';
        const showSql=settingsTab==='sql';
        $('#settingsUpdatePanel').hidden=showSql;
        sqlPanel.hidden=!showSql;
        $$('[data-settings-tab]').forEach(button=>{
          const selected=button.dataset.settingsTab===settingsTab;
          button.classList.toggle('active',selected);
          button.setAttribute('aria-selected',String(selected));
          button.tabIndex=selected?0:-1;
        });
        if(showSql&&!sqlPanel.dataset.initialized){renderSql(sqlPanel);sqlPanel.dataset.initialized='true';}
      }
      $$('[data-settings-tab]').forEach(button=>{
        button.onclick=()=>setSettingsTab(button.dataset.settingsTab);
        button.onkeydown=e=>{
          const next=({ArrowRight:settingsTab==='update'?'sql':'update',ArrowLeft:settingsTab==='update'?'sql':'update',Home:'update',End:'sql'})[e.key];
          if(!next)return;
          e.preventDefault();setSettingsTab(next);
          $(`[data-settings-tab="${next}"]`).focus();
        };
      });
      setSettingsTab(settingsTab);
      const galleryResult = $('#galleryResult');
      const galleryList = $('#galleryList');
      let galleryData = null;
      let busyGallery = false;
      function showGallery(data) {
        galleryData=data;
        const items=Array.isArray(data.images)?data.images:[];
        const enabled=data.enabled===true;
        $('#galleryStatus').textContent=`${items.length} of ${Number(data.max_images||40)} pictures · ${enabled?'Slideshow enabled':'Slideshow disabled'} · Login pictures are public`;
        const toggle=$('#galleryToggle');
        toggle.textContent=enabled?'Disable slideshow':'Enable slideshow';
        toggle.disabled=busyGallery;
        galleryList.innerHTML=items.length?items.map(p=>`<div class="login-gallery-item"><img src="${h(p.url)}" alt="" loading="lazy"><div class="login-gallery-meta"><div class="master-meta" title="${h(p.name)}">${h(p.name)}</div><button type="button" class="secondary" data-gallery-id="${h(p.id)}">Remove</button></div></div>`).join(''):'<div class="muted small">No login photos uploaded yet. The original login background is used until photos are added.</div>';
      }
      async function galleryRequest(data) {
        const rr=await fetch('login-images.php',{method:'POST',headers:{'X-CSRF-Token':state.csrf},body:data});
        const raw=await rr.text();
        let j;try{j=JSON.parse(raw);}catch{throw Error(`Unexpected gallery response (HTTP ${rr.status}).`);}
        if(!rr.ok)throw Error(j.error||`Picture operation failed (HTTP ${rr.status}).`);
        return j;
      }
      async function loadGallery() {
        try {
          const r=await fetch('login-images.php',{cache:'no-store'});
          const j=await r.json();if(!r.ok)throw Error(j.error||'Gallery unavailable.');
          showGallery(j);
        }catch(e){$('#galleryStatus').textContent=e.message;galleryResult.innerHTML=errorHtml(e);}
      }
      $('#galleryUploadForm').onsubmit=async e=>{
        e.preventDefault();if(busyGallery)return;
        const files=Array.from($('#galleryPhotoInput').files||[]);
        if(!files.length){toast('Select at least one picture.','error');return;}
        if(files.length>8||files.some(f=>f.size>8*1024*1024||f.size<1)){toast('Upload up to eight pictures, each 8 MB or less.','error');return;}
        if((galleryData?.images?.length||0)+files.length>40){toast('Maximum 40 login pictures.','error');return;}
        busyGallery=true;const btn=e.target.querySelector('button[type="submit"]');btn.disabled=true;
        galleryResult.innerHTML='<div class="notice">Optimizing and saving login pictures…</div>';
        try{
          const body=new FormData();body.append('action','upload');files.forEach(f=>body.append('photos[]',f,f.name));
          const j=await galleryRequest(body);showGallery(j);e.target.reset();galleryResult.innerHTML='<div class="notice success">Pictures added to the login slideshow.</div>';
        }catch(err){galleryResult.innerHTML=errorHtml(err);}finally{busyGallery=false;btn.disabled=false;if(galleryData)showGallery(galleryData);}
      };
      $('#galleryToggle').onclick=async()=>{
        if(busyGallery||!galleryData)return;
        busyGallery=true;$('#galleryToggle').disabled=true;
        try{
          const body=new FormData();body.append('action','toggle');body.append('enabled',galleryData.enabled?'0':'1');
          const j=await galleryRequest(body);showGallery(j);galleryResult.innerHTML='<div class="notice success">Slideshow setting saved.</div>';
        }catch(err){galleryResult.innerHTML=errorHtml(err);}finally{busyGallery=false;if(galleryData)showGallery(galleryData);}
      };
      galleryList.onclick=async e=>{
        const btn=e.target.closest('button[data-gallery-id]');if(!btn||busyGallery)return;
        const id=btn.dataset.galleryId;
        if(!confirm('Remove this photo from the login slideshow?'))return;
        busyGallery=true;btn.disabled=true;
        try{
          const body=new FormData();body.append('action','remove');body.append('id',id);
          const j=await galleryRequest(body);showGallery(j);galleryResult.innerHTML='<div class="notice success">Picture removed.</div>';
        }catch(err){galleryResult.innerHTML=errorHtml(err);}finally{busyGallery=false;if(galleryData)showGallery(galleryData);}
      };
      loadGallery();
      const reviewPanel = $('#updateReview');
      const resultPanel = $('#updateResult');
      let reviewedToken = null;
      let busyUpdate = false;
      async function updateRequest(payload) {
        const rr = await fetch('update.php', {
          method:'POST', headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-Token':state.csrf},
          body:JSON.stringify(payload)
        });
        const raw = await rr.text();
        let j;
        try {j = JSON.parse(raw);}
        catch {
          const plain=raw.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim().slice(0,240);
          throw Error(`Hostinger returned a non-JSON response (HTTP ${rr.status}). ${plain||'The request may have been blocked by the hosting security layer.'}`);
        }
        if(!rr.ok)throw Error(j.error||`Update request failed (HTTP ${rr.status}).`);
        return j;
      }
      function clearReviewUi() {
        reviewedToken=null;
        reviewPanel.hidden=true;
        reviewPanel.innerHTML='';
      }
      $('#updateForm input[name="update"]').onchange=async()=>{
        if(!reviewedToken || busyUpdate)return;
        clearReviewUi();
        resultPanel.innerHTML='<div class="notice">ZIP selection changed. Upload and Review the new package before installing.</div>';
        try{await updateRequest({action:'cancel'});}catch(err){resultPanel.innerHTML=errorHtml(err);}
      };
      $('#updateForm').onsubmit=async e=>{
        e.preventDefault();
        if(busyUpdate)return;
        const file=e.target.elements.update?.files?.[0];
        if(!file){resultPanel.innerHTML=errorHtml('Choose an update ZIP file.');return;}
        if(!/\.zip$/i.test(file.name)){resultPanel.innerHTML=errorHtml('Choose a ZIP update package.');return;}
        if(file.size>30*1024*1024){resultPanel.innerHTML=errorHtml('This update is larger than 30 MB. Use Hostinger File Manager for a major release.');return;}
        busyUpdate=true;
        const btn=$('#updateForm button[type="submit"]');btn.disabled=true;
        clearReviewUi();
        resultPanel.innerHTML='<div class="notice">Uploading and validating the update for review. Nothing is being installed…</div>';
        try {
          const dataUrl=await new Promise((resolve,reject)=>{
            const reader=new FileReader();
            reader.onload=()=>resolve(String(reader.result||''));
            reader.onerror=()=>reject(Error('The selected update file could not be read.'));
            reader.readAsDataURL(file);
          });
          const j=await updateRequest({action:'review',filename:file.name,data_base64:dataUrl.split(',',2)[1]||''});
          reviewedToken=j.review_token;
          const d=j.details;
          if(!d||!reviewedToken)throw Error('No update review details were returned.');
          reviewPanel.hidden=false;
          reviewPanel.innerHTML=`<section class="update-review-details"><h3>Review update details</h3>
            <div class="update-review-grid">
              <div><span>Application</span><strong>${h(d.product)}</strong></div>
              <div><span>Version</span><strong>v${h(d.current_version)} → v${h(d.version)}</strong></div>
              <div><span>Required app version</span><strong>v${h(d.minimum_version||'Not specified')}</strong></div>
              <div><span>Required PHP version</span><strong>${h(d.minimum_php||'Not specified')}</strong></div>
            </div>
            <p><strong>Update summary:</strong> ${h(d.description||'See release notes below.')}</p>
            <h4>Release notes</h4><pre class="update-release-notes">${h(d.release_notes||'No additional release notes supplied.')}</pre>
            <details><summary>Files to be updated (${Number(d.file_count||0)})</summary><ul>${(d.files||[]).map(f=>`<li><code>${h(f)}</code></li>`).join('')}</ul></details>
            <p class="muted small">ZIP size: ${h(new Intl.NumberFormat('en-PH').format(Number(d.zip_size||0)))} bytes. Review expires after 15 minutes. SHA-256: <code class="update-hash">${h(d.sha256)}</code></p>
            <p class="notice">Installing will back up application code and the database before replacing files. Review the release source independently; checksums alone do not prove publisher identity.</p>
            <label class="update-consent"><input id="confirmUpdateReview" type="checkbox" required> I have reviewed the update details and understand that installing will change the application.</label>
            <div class="actions"><button id="installReviewedUpdate" type="button" class="primary" disabled>Install Update</button><button id="cancelReviewedUpdate" type="button" class="secondary">Cancel Review</button></div>
          </section>`;
          resultPanel.innerHTML='<div class="notice success">Update package validated. Review the details below; installation has not started.</div>';
          const checkbox=$('#confirmUpdateReview');
          const installBtn=$('#installReviewedUpdate');
          checkbox.onchange=()=>{installBtn.disabled=!checkbox.checked;};
          $('#cancelReviewedUpdate').onclick=async()=>{
            if(busyUpdate)return;
            busyUpdate=true;installBtn.disabled=true;
            try{await updateRequest({action:'cancel'});clearReviewUi();resultPanel.innerHTML='<div class="notice">Review cancelled. No application files were changed.</div>';}
            catch(err){resultPanel.innerHTML=errorHtml(err);}
            finally{busyUpdate=false;}
          };
          installBtn.onclick=async()=>{
            if(busyUpdate||!reviewedToken||!checkbox.checked)return;
            busyUpdate=true;installBtn.disabled=true;
            $('#cancelReviewedUpdate').disabled=true;
            resultPanel.innerHTML='<div class="notice">Creating backups and installing the reviewed update…</div>';
            try{
              const j=await updateRequest({action:'install',review_token:reviewedToken,confirmed:true});
              clearReviewUi();
              resultPanel.innerHTML=`<div class="notice success">${h(j.message)}<br>Code backup: ${h(j.backup)}<br>Database backup: ${h(j.database_backup)}<br><strong>Reload the page to complete the update.</strong></div>`;
              toast(`Updated files to v${j.to}. Reload now.`);
            }catch(err){
              // Installation attempts consume their review. Re-upload to retry safely.
              clearReviewUi();resultPanel.innerHTML=errorHtml(err);
            }finally{busyUpdate=false;}
          };
        }catch(err){clearReviewUi();resultPanel.innerHTML=errorHtml(err);}
        finally{busyUpdate=false;btn.disabled=false;}
      };}catch(e){main.innerHTML=errorHtml(e);}}

  function renderSql(container){if(!isOwner()){container.innerHTML='<div class="notice error">Project Owner access is required.</div>';return;}container.innerHTML=`<section class="panel"><div class="notice warn"><strong>Production diagnostic tool.</strong> SQL Console is read-only. Use SELECT, SHOW, DESCRIBE or EXPLAIN. Database changes must go through application workflows or reviewed migrations.</div><label>SQL statement<textarea id="sqlText" class="codebox" style="color:#d7e3f0" spellcheck="false">SELECT VERSION() AS database_version</textarea></label><div class="actions"><button class="primary" id="runSql">Run query</button></div><div id="sqlOut" class="sql-result"></div></section>`;const runSql=container.querySelector('#runSql');runSql.onclick=async()=>{const out=container.querySelector('#sqlOut');out.innerHTML='<div class="notice">Running query…</div>';try{const r=await fetch('sql-console.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},body:JSON.stringify({sql:container.querySelector('#sqlText').value})});const j=await r.json();if(!r.ok)throw Error(j.error||'SQL execution failed.');out.innerHTML=j.rows.length?`<div class="table-wrap"><table><thead><tr>${Object.keys(j.rows[0]).map(k=>`<th>${h(k)}</th>`).join('')}</tr></thead><tbody>${j.rows.map(row=>`<tr>${Object.values(row).map(v=>`<td>${h(typeof v==='object'?JSON.stringify(v):v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${j.truncated?'<p class="muted small">Only the first 200 rows are shown.</p>':''}`:'<div class="notice success">Query completed with no rows.</div>';}catch(e){out.innerHTML=errorHtml(e);}};}

  function openModal(t,d,html){modal.style.width='';modalTitle.textContent=t;modalDesc.textContent=d||'';modalBody.innerHTML=html;modal.showModal();}
  function downloadBlob(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}

  async function buildCertificateBlob(t){if(!window.PDFLib)throw Error('PDF library could not be loaded. Check the internet connection and try again.');const verified=await api({action:'certificate',id:t.id});let s=verified.snapshot;if(!s||!['submitted','checked','void'].includes(t.status))throw Error('Form 2307 is available after the Draft is submitted.');const response=await fetch('assets/bir2307-v1.pdf');if(!response.ok)throw Error('Certificate template is unavailable.');const {PDFDocument,StandardFonts,rgb}=window.PDFLib;const doc=await PDFDocument.load(await response.arrayBuffer());const page=doc.getPages()[0];const font=await doc.embedFont(StandardFonts.Helvetica);const draw=(value,x,y,max=520,size=10,min=5)=>{const str=String(value??'');const width=font.widthOfTextAtSize(str,size);const scaled=width>max?size*max/width:size;if(scaled<min)throw Error('A certificate field is too long to print legibly. Contact the Division administrator.');page.drawText(str,{x,y,size:scaled,font,color:rgb(0,0,0)});};const digits=(str,x,y,spacing)=>{for(const c of String(str)){draw(c,x,y,15,11);x+=spacing;}};const tin=(value,y)=>{const n=String(value).replace(/\D/g,'').padEnd(14,'0');let x=210;[n.slice(0,3),n.slice(3,6),n.slice(6,9),n.slice(9,14)].forEach((part,i)=>{digits(part,x,y,i===3?14:11.25);x+=part.length*(i===3?14:11.25)+19;});};const dt=(value,x)=>{const [yy,mm,dd]=value.split('-');for(const part of [mm,dd,yy]){digits(part,x,818,12);x+=part.length*12+4;}};const wrapText=(value,size,max)=>{const words=String(value??'').trim().split(/\s+/).filter(Boolean),lines=[];let line='';for(const word of words){const candidate=(line+' '+word).trim();if(font.widthOfTextAtSize(candidate,size)<=max){line=candidate;continue;}if(line){lines.push(line);line='';}if(font.widthOfTextAtSize(word,size)<=max){line=word;continue;}let part='';for(const ch of word){if(font.widthOfTextAtSize(part+ch,size)>max&&part){lines.push(part);part=ch;}else part+=ch;}line=part;}if(line)lines.push(line);return lines;};const description=(value,y)=>{const max=143,size=8,rowStep=13.75,maxRows=10,lines=wrapText(value,size,max);if(lines.length>maxRows)throw Error('ATC description is too long for the available certificate rows. Shorten the ATC description in the master record.');lines.forEach((line,i)=>draw(line,28,y+1.5-(i*rowStep),max,size,5));};dt(s.period.from,155);dt(s.period.to,403);tin(s.supplier.tin,787);tin(s.division.tin,672);draw(s.supplier.name,50,760,530,11);draw(s.supplier.address,50,732,477,10);digits(s.supplier.zip,545,732,13);draw(s.division.name,50,645,530,11);draw(s.division.address,50,617,477,10);digits(s.division.zip,545,617,13);const fm=n=>(n/100).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});const month=Number(s.date.slice(5,7));const mx=[230,300,390][(month-1)%3];for(const [code,y,amount,totalY] of [[s.ewt,560,s.amounts.ewt,425],[s.business,390,s.amounts.business,255]]){draw(code.name,180,y,43,9);description(code.description,y);draw(fm(s.amounts.base),mx,y,62,9);draw(fm(s.amounts.base),450,y,67,9);draw(fm(amount),550,y,55,9);draw(fm(amount),550,totalY,55,9);}const centerDraw=(value,y,max=540,size=9,min=4.5)=>{const str=String(value??'');if(!str)return;const raw=font.widthOfTextAtSize(str,size),fitted=raw>max?size*max/raw:size;if(fitted<min)throw Error('Representative information is too long to print legibly.');const width=font.widthOfTextAtSize(str,fitted);page.drawText(str,{x:(page.getWidth()-width)/2,y,size:fitted,font,color:rgb(0,0,0)});};const rep=s.representative||{name:s.school?.representative||'',position:s.school?.position||'',tin:s.school?.representative_tin||''};const name=rep.name,position=[rep.position,rep.tin].filter(Boolean).join(' | ');centerDraw(name,203.5,540,8.5,5.5);centerDraw(position,191.5,540,7,4.5);if(t.status==='void')page.drawText('VOID',{x:210,y:450,size:70,font,color:rgb(.8,.1,.1),opacity:.4});doc.setTitle(`BIR 2307 - ${transactionReference(t)}`);doc.setSubject(`Origin: ${s.transaction_scope==='division'?(s.division?.name||'Division Office'):(s.school?.name||'School')}; transaction: ${transactionReference(t)}`);const bytes=await doc.save();return new Blob([bytes],{type:'application/pdf'});}
  async function downloadCertificate(t){const blob=await buildCertificateBlob(t);downloadBlob(blob,`2307-${t.id}.pdf`);}
  async function printCertificate(t){const w=window.open('','_blank');if(!w)throw Error('Allow pop-ups for this site to print Form 2307.');try{w.document.write('<!doctype html><title>Preparing Form 2307…</title><p style="font-family:Arial,sans-serif;padding:24px">Preparing Form 2307…</p>');const blob=await buildCertificateBlob(t),url=URL.createObjectURL(blob);w.location.href=url;setTimeout(()=>URL.revokeObjectURL(url),120000);}catch(e){w.close();throw e;}}

  const notificationBtn=$('#notificationBtn'),notificationPanel=$('#notificationPanel');if(notificationBtn&&notificationPanel){notificationBtn.onclick=e=>{e.stopPropagation();const opening=notificationPanel.hidden;notificationPanel.hidden=!opening;notificationBtn.setAttribute('aria-expanded',opening?'true':'false');if(opening)renderNotifications();};document.addEventListener('click',e=>{if(!notificationPanel.hidden&&!e.target.closest('.notification-wrap')){notificationPanel.hidden=true;notificationBtn.setAttribute('aria-expanded','false');}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!notificationPanel.hidden){notificationPanel.hidden=true;notificationBtn.setAttribute('aria-expanded','false');}});}
  $('#refreshBtn').onclick=()=>load().then(()=>toast('Data refreshed.')).catch(e=>toast(e.message,'error'));$('#menuBtn').onclick=()=>document.body.classList.toggle('sidebar-open');const modalClose=$('#modalClose');if(modalClose)modalClose.addEventListener('click',()=>{modal.close();modal.style.width='';});modal.addEventListener('click',e=>{if(e.target===modal){modal.close();modal.style.width='';}});load();setInterval(()=>{if(document.visibilityState==='visible')refreshNotifications();},30000);
})();
